    fn shebang_parsing_bash() {
        let info = parse_shebang("#!/bin/bash");
        assert!(info.is_some());
    }

    #[test]
    fn shebang_parsing_none() {
        let info = parse_shebang("not a shebang");
        assert!(info.is_none());
    }

