// --- bck_: Editor dialog / message box model ---

/// Dialog severity icon.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BckDialogSeverity { Info, Warning, Error, None }

/// A dialog button.
#[derive(Debug, Clone)]
pub struct BckDialogButton {
    pub id: String,
    pub label: String,
    pub is_close: bool,
}

impl BckDialogButton {
    pub fn new(id: &str, label: &str) -> Self { Self { id: id.to_string(), label: label.to_string(), is_close: false } }
    pub fn close(id: &str, label: &str) -> Self { Self { id: id.to_string(), label: label.to_string(), is_close: true } }
}

/// A dialog with message and buttons.
#[derive(Debug)]
pub struct BckDialog {
    severity: BckDialogSeverity,
    message: String,
    detail: Option<String>,
    buttons: Vec<BckDialogButton>,
    checkbox_label: Option<String>,
    checkbox_checked: bool,
    selected_button: usize,
}

impl BckDialog {
    pub fn new(sev: BckDialogSeverity, message: &str) -> Self {
        Self { severity: sev, message: message.to_string(), detail: None, buttons: Vec::new(), checkbox_label: None, checkbox_checked: false, selected_button: 0 }
    }

    pub fn info(msg: &str) -> Self { Self::new(BckDialogSeverity::Info, msg) }
    pub fn warning(msg: &str) -> Self { Self::new(BckDialogSeverity::Warning, msg) }
    pub fn error(msg: &str) -> Self { Self::new(BckDialogSeverity::Error, msg) }

    pub fn with_detail(mut self, d: &str) -> Self { self.detail = Some(d.to_string()); self }
    pub fn with_button(mut self, b: BckDialogButton) -> Self { self.buttons.push(b); self }
    pub fn with_checkbox(mut self, label: &str) -> Self { self.checkbox_label = Some(label.to_string()); self }

    pub fn message(&self) -> &str { &self.message }
    pub fn detail(&self) -> Option<&str> { self.detail.as_deref() }
    pub fn severity(&self) -> BckDialogSeverity { self.severity }
    pub fn buttons(&self) -> &[BckDialogButton] { &self.buttons }
    pub fn has_checkbox(&self) -> bool { self.checkbox_label.is_some() }
    pub fn is_checkbox_checked(&self) -> bool { self.checkbox_checked }

    pub fn toggle_checkbox(&mut self) { self.checkbox_checked = !self.checkbox_checked; }

    pub fn move_selection(&mut self, delta: i32) {
        if self.buttons.is_empty() { return; }
        let n = self.buttons.len() as i32;
        self.selected_button = ((self.selected_button as i32 + delta).rem_euclid(n)) as usize;
    }

    pub fn selected_button(&self) -> Option<&BckDialogButton> { self.buttons.get(self.selected_button) }

    pub fn confirm_save_dialog(filename: &str) -> Self {
        Self::warning(&format!("Do you want to save changes to {}?", filename))
            .with_detail("Your changes will be lost if you don't save them.")
            .with_button(BckDialogButton::new("save", "Save"))
            .with_button(BckDialogButton::new("dont_save", "Don't Save"))
            .with_button(BckDialogButton::close("cancel", "Cancel"))
    }

    pub fn render(&self, width: usize) -> Vec<String> {
        let mut lines = Vec::new();
        let icon = match self.severity { BckDialogSeverity::Info => "ℹ ", BckDialogSeverity::Warning => "⚠ ", BckDialogSeverity::Error => "✗ ", BckDialogSeverity::None => "" };
        lines.push(format!("{}{}", icon, self.message));
        if let Some(d) = &self.detail { lines.push(format!("  {}", d)); }
        if let Some(cb) = &self.checkbox_label {
            let mark = if self.checkbox_checked { "☑" } else { "☐" };
            lines.push(format!("  {} {}", mark, cb));
        }
        let btns: String = self.buttons.iter().enumerate().map(|(i, b)| {
            if i == self.selected_button { format!(" [{}] ", b.label) } else { format!("  {}  ", b.label) }
        }).collect();
        if !btns.is_empty() { lines.push(btns[..btns.len().min(width)].to_string()); }
        lines
    }
}

#[cfg(test)]
mod bck_tests {
    use super::*;

    #[test]
    fn test_bck_info() {
        let d = BckDialog::info("Hello");
        assert_eq!(d.severity(), BckDialogSeverity::Info);
        assert_eq!(d.message(), "Hello");
    }

    #[test]
    fn test_bck_buttons() {
        let d = BckDialog::warning("Sure?").with_button(BckDialogButton::new("ok", "OK"));
        assert_eq!(d.buttons().len(), 1);
    }

    #[test]
    fn test_bck_selection() {
        let mut d = BckDialog::info("X").with_button(BckDialogButton::new("a", "A")).with_button(BckDialogButton::new("b", "B"));
        assert_eq!(d.selected_button().unwrap().id, "a");
        d.move_selection(1);
        assert_eq!(d.selected_button().unwrap().id, "b");
    }

    #[test]
    fn test_bck_checkbox() {
        let mut d = BckDialog::info("X").with_checkbox("Don't show again");
        assert!(d.has_checkbox());
        assert!(!d.is_checkbox_checked());
        d.toggle_checkbox();
        assert!(d.is_checkbox_checked());
    }

    #[test]
    fn test_bck_confirm_save() {
        let d = BckDialog::confirm_save_dialog("main.rs");
        assert!(d.message().contains("main.rs"));
        assert_eq!(d.buttons().len(), 3);
    }

    #[test]
    fn test_bck_render() {
        let d = BckDialog::error("Failed").with_detail("Check logs");
        let lines = d.render(60);
        assert!(lines[0].contains("✗"));
        assert!(lines.len() >= 2);
    }

    #[test]
    fn test_bck_wrap_selection() {
        let mut d = BckDialog::info("X").with_button(BckDialogButton::new("a", "A")).with_button(BckDialogButton::new("b", "B"));
        d.move_selection(-1); // wraps to last
        assert_eq!(d.selected_button().unwrap().id, "b");
    }

    #[test]
    fn test_bck_detail() {
        let d = BckDialog::info("X").with_detail("Details here");
        assert_eq!(d.detail(), Some("Details here"));
    }

    #[test]
    fn test_bck_close_button() {
        let b = BckDialogButton::close("cancel", "Cancel");
        assert!(b.is_close);
    }

    #[test]
    fn test_bck_no_buttons() {
        let d = BckDialog::info("Simple");
        assert!(d.selected_button().is_none());
    }
}


// --- bcl_: Editor file dialog model ---

/// File dialog mode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BclDialogMode { Open, Save, OpenFolder }

/// A file entry in the dialog.
#[derive(Debug, Clone)]
pub struct BclFileEntry {
    pub name: String,
    pub is_dir: bool,
    pub size: u64,
    pub modified: u64,
}

impl BclFileEntry {
    pub fn dir(name: &str) -> Self { Self { name: name.to_string(), is_dir: true, size: 0, modified: 0 } }
    pub fn file(name: &str, size: u64) -> Self { Self { name: name.to_string(), is_dir: false, size, modified: 0 } }

    pub fn icon(&self) -> char { if self.is_dir { '📁' } else { '📄' } }

    pub fn display(&self) -> String {
        if self.is_dir { format!("{} {}/", self.icon(), self.name) }
        else { format!("{} {} ({})", self.icon(), self.name, self.human_size()) }
    }

    pub fn human_size(&self) -> String {
        if self.size < 1024 { format!("{} B", self.size) }
        else if self.size < 1024 * 1024 { format!("{:.1} KB", self.size as f64 / 1024.0) }
        else { format!("{:.1} MB", self.size as f64 / (1024.0 * 1024.0)) }
    }

    pub fn matches_filter(&self, filter: &str) -> bool {
        if filter.is_empty() { return true; }
        self.name.to_lowercase().contains(&filter.to_lowercase())
    }
}

/// The file dialog model.
#[derive(Debug)]
pub struct BclFileDialog {
    mode: BclDialogMode,
    current_path: String,
    entries: Vec<BclFileEntry>,
    filter: String,
    cursor: usize,
    filename_input: String,
    show_hidden: bool,
    filters: Vec<(String, Vec<String>)>,
    active_filter: usize,
}

impl BclFileDialog {
    pub fn new(mode: BclDialogMode, path: &str) -> Self {
        Self { mode, current_path: path.to_string(), entries: Vec::new(), filter: String::new(), cursor: 0, filename_input: String::new(), show_hidden: false, filters: Vec::new(), active_filter: 0 }
    }

    pub fn mode(&self) -> BclDialogMode { self.mode }
    pub fn current_path(&self) -> &str { &self.current_path }

    pub fn set_entries(&mut self, entries: Vec<BclFileEntry>) {
        self.entries = entries;
        self.entries.sort_by(|a, b| b.is_dir.cmp(&a.is_dir).then(a.name.cmp(&b.name)));
        self.cursor = 0;
    }

    pub fn set_filter(&mut self, f: &str) { self.filter = f.to_string(); self.cursor = 0; }

    pub fn visible_entries(&self) -> Vec<&BclFileEntry> {
        self.entries.iter().filter(|e| {
            if !self.show_hidden && e.name.starts_with('.') { return false; }
            e.matches_filter(&self.filter)
        }).collect()
    }

    pub fn cursor_entry(&self) -> Option<&BclFileEntry> { self.visible_entries().get(self.cursor).copied() }

    pub fn move_cursor(&mut self, delta: i32) {
        let count = self.visible_entries().len();
        if count == 0 { return; }
        self.cursor = ((self.cursor as i32 + delta).rem_euclid(count as i32)) as usize;
    }

    pub fn navigate_into(&mut self) -> bool {
        if let Some(entry) = self.cursor_entry() {
            if entry.is_dir {
                let name = entry.name.clone();
                if name == ".." {
                    if let Some(parent) = self.current_path.rsplit_once('/') {
                        self.current_path = if parent.0.is_empty() { "/".to_string() } else { parent.0.to_string() };
                    }
                } else {
                    self.current_path = format!("{}/{}", self.current_path.trim_end_matches('/'), name);
                }
                self.entries.clear();
                self.cursor = 0;
                return true;
            }
        }
        false
    }

    pub fn selected_path(&self) -> Option<String> {
        match self.mode {
            BclDialogMode::Save => {
                if self.filename_input.is_empty() { None }
                else { Some(format!("{}/{}", self.current_path.trim_end_matches('/'), self.filename_input)) }
            }
            BclDialogMode::OpenFolder => Some(self.current_path.clone()),
            BclDialogMode::Open => self.cursor_entry().filter(|e| !e.is_dir).map(|e| format!("{}/{}", self.current_path.trim_end_matches('/'), e.name)),
        }
    }

    pub fn set_filename(&mut self, name: &str) { self.filename_input = name.to_string(); }
    pub fn toggle_hidden(&mut self) { self.show_hidden = !self.show_hidden; }

    pub fn add_filter(&mut self, label: &str, exts: Vec<String>) { self.filters.push((label.to_string(), exts)); }
}

#[cfg(test)]
mod bcl_tests {
    use super::*;

    #[test]
    fn test_bcl_new() {
        let d = BclFileDialog::new(BclDialogMode::Open, "/home/user");
        assert_eq!(d.mode(), BclDialogMode::Open);
        assert_eq!(d.current_path(), "/home/user");
    }

    #[test]
    fn test_bcl_entries_sorted() {
        let mut d = BclFileDialog::new(BclDialogMode::Open, "/");
        d.set_entries(vec![BclFileEntry::file("b.txt", 100), BclFileEntry::dir("adir")]);
        assert!(d.visible_entries()[0].is_dir); // dirs first
    }

    #[test]
    fn test_bcl_filter() {
        let mut d = BclFileDialog::new(BclDialogMode::Open, "/");
        d.set_entries(vec![BclFileEntry::file("main.rs", 500), BclFileEntry::file("lib.rs", 300)]);
        d.set_filter("main");
        assert_eq!(d.visible_entries().len(), 1);
    }

    #[test]
    fn test_bcl_hidden() {
        let mut d = BclFileDialog::new(BclDialogMode::Open, "/");
        d.set_entries(vec![BclFileEntry::file(".gitignore", 50), BclFileEntry::file("readme", 100)]);
        assert_eq!(d.visible_entries().len(), 1);
        d.toggle_hidden();
        assert_eq!(d.visible_entries().len(), 2);
    }

    #[test]
    fn test_bcl_cursor() {
        let mut d = BclFileDialog::new(BclDialogMode::Open, "/");
        d.set_entries(vec![BclFileEntry::file("a", 1), BclFileEntry::file("b", 2)]);
        d.move_cursor(1);
        assert_eq!(d.cursor_entry().unwrap().name, "b");
    }

    #[test]
    fn test_bcl_navigate_into() {
        let mut d = BclFileDialog::new(BclDialogMode::Open, "/home");
        d.set_entries(vec![BclFileEntry::dir("user"), BclFileEntry::file("f", 1)]);
        assert!(d.navigate_into());
        assert_eq!(d.current_path(), "/home/user");
    }

    #[test]
    fn test_bcl_save_path() {
        let mut d = BclFileDialog::new(BclDialogMode::Save, "/home/user");
        d.set_filename("new.rs");
        assert_eq!(d.selected_path(), Some("/home/user/new.rs".to_string()));
    }

    #[test]
    fn test_bcl_open_folder() {
        let d = BclFileDialog::new(BclDialogMode::OpenFolder, "/workspace");
        assert_eq!(d.selected_path(), Some("/workspace".to_string()));
    }

    #[test]
    fn test_bcl_file_display() {
        let f = BclFileEntry::file("test.rs", 2048);
        assert!(f.display().contains("2.0 KB"));
    }

    #[test]
    fn test_bcl_human_size() {
        assert_eq!(BclFileEntry::file("x", 500).human_size(), "500 B");
        assert!(BclFileEntry::file("x", 1500000).human_size().contains("MB"));
    }
}


// --- bcm_: Editor progress indicator model ---

/// Progress location in the UI.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BcmProgressLocation { Notification, StatusBar, Window }

/// A progress task.
#[derive(Debug, Clone)]
pub struct BcmProgressTask {
    pub id: u64,
    pub title: String,
    pub location: BcmProgressLocation,
    pub percentage: Option<f64>,
    pub message: Option<String>,
    pub cancellable: bool,
    pub cancelled: bool,
    pub done: bool,
}

impl BcmProgressTask {
    pub fn new(id: u64, title: &str, loc: BcmProgressLocation) -> Self {
        Self { id, title: title.to_string(), location: loc, percentage: None, message: None, cancellable: false, cancelled: false, done: false }
    }

    pub fn with_cancellable(mut self) -> Self { self.cancellable = true; self }

    pub fn report(&mut self, pct: Option<f64>, msg: Option<&str>) {
        self.percentage = pct;
        self.message = msg.map(|s| s.to_string());
    }

    pub fn finish(&mut self) { self.done = true; self.percentage = Some(100.0); }
    pub fn cancel(&mut self) { if self.cancellable { self.cancelled = true; self.done = true; } }

    pub fn is_indeterminate(&self) -> bool { self.percentage.is_none() && !self.done }

    pub fn render_bar(&self, width: usize) -> String {
        if self.done {
            let status = if self.cancelled { "Cancelled" } else { "Done" };
            return format!("{}: {}", self.title, status);
        }
        match self.percentage {
            Some(pct) => {
                let filled = ((pct / 100.0) * width as f64) as usize;
                let empty = width.saturating_sub(filled);
                let bar = format!("{}{}", "█".repeat(filled), "░".repeat(empty));
                let msg = self.message.as_deref().unwrap_or("");
                format!("{}: [{}] {:.0}% {}", self.title, bar, pct, msg)
            }
            None => {
                let msg = self.message.as_deref().unwrap_or("");
                format!("{}: ⠋ {} ", self.title, msg)
            }
        }
    }
}

/// Manages all active progress tasks.
#[derive(Debug)]
pub struct BcmProgressManager {
    tasks: Vec<BcmProgressTask>,
    next_id: u64,
}

impl BcmProgressManager {
    pub fn new() -> Self { Self { tasks: Vec::new(), next_id: 1 } }

    pub fn start(&mut self, title: &str, loc: BcmProgressLocation) -> u64 {
        let id = self.next_id;
        self.next_id += 1;
        self.tasks.push(BcmProgressTask::new(id, title, loc));
        id
    }

    pub fn start_cancellable(&mut self, title: &str, loc: BcmProgressLocation) -> u64 {
        let id = self.next_id;
        self.next_id += 1;
        self.tasks.push(BcmProgressTask::new(id, title, loc).with_cancellable());
        id
    }

    pub fn report(&mut self, id: u64, pct: Option<f64>, msg: Option<&str>) {
        if let Some(t) = self.tasks.iter_mut().find(|t| t.id == id) { t.report(pct, msg); }
    }

    pub fn finish(&mut self, id: u64) {
        if let Some(t) = self.tasks.iter_mut().find(|t| t.id == id) { t.finish(); }
    }

    pub fn cancel(&mut self, id: u64) {
        if let Some(t) = self.tasks.iter_mut().find(|t| t.id == id) { t.cancel(); }
    }

    pub fn active_tasks(&self) -> Vec<&BcmProgressTask> { self.tasks.iter().filter(|t| !t.done).collect() }
    pub fn all_tasks(&self) -> &[BcmProgressTask] { &self.tasks }
    pub fn cleanup_done(&mut self) { self.tasks.retain(|t| !t.done); }

    pub fn by_location(&self, loc: BcmProgressLocation) -> Vec<&BcmProgressTask> {
        self.tasks.iter().filter(|t| t.location == loc && !t.done).collect()
    }
}

#[cfg(test)]
mod bcm_tests {
    use super::*;

    #[test]
    fn test_bcm_start() {
        let mut pm = BcmProgressManager::new();
        let id = pm.start("Loading", BcmProgressLocation::Notification);
        assert_eq!(pm.active_tasks().len(), 1);
        assert_eq!(id, 1);
    }

    #[test]
    fn test_bcm_report() {
        let mut pm = BcmProgressManager::new();
        let id = pm.start("Indexing", BcmProgressLocation::Window);
        pm.report(id, Some(50.0), Some("halfway"));
        let t = &pm.all_tasks()[0];
        assert_eq!(t.percentage, Some(50.0));
    }

    #[test]
    fn test_bcm_finish() {
        let mut pm = BcmProgressManager::new();
        let id = pm.start("Build", BcmProgressLocation::StatusBar);
        pm.finish(id);
        assert_eq!(pm.active_tasks().len(), 0);
    }

    #[test]
    fn test_bcm_cancel() {
        let mut pm = BcmProgressManager::new();
        let id = pm.start_cancellable("Search", BcmProgressLocation::Notification);
        pm.cancel(id);
        assert!(pm.all_tasks()[0].cancelled);
    }

    #[test]
    fn test_bcm_indeterminate() {
        let t = BcmProgressTask::new(1, "Loading", BcmProgressLocation::Notification);
        assert!(t.is_indeterminate());
    }

    #[test]
    fn test_bcm_render_bar() {
        let mut t = BcmProgressTask::new(1, "Build", BcmProgressLocation::Window);
        t.report(Some(50.0), None);
        let bar = t.render_bar(10);
        assert!(bar.contains("50%"));
    }

    #[test]
    fn test_bcm_render_done() {
        let mut t = BcmProgressTask::new(1, "X", BcmProgressLocation::Window);
        t.finish();
        assert!(t.render_bar(10).contains("Done"));
    }

    #[test]
    fn test_bcm_by_location() {
        let mut pm = BcmProgressManager::new();
        pm.start("A", BcmProgressLocation::StatusBar);
        pm.start("B", BcmProgressLocation::Notification);
        assert_eq!(pm.by_location(BcmProgressLocation::StatusBar).len(), 1);
    }

    #[test]
    fn test_bcm_cleanup() {
        let mut pm = BcmProgressManager::new();
        let id = pm.start("X", BcmProgressLocation::Window);
        pm.finish(id);
        pm.cleanup_done();
        assert!(pm.all_tasks().is_empty());
    }

    #[test]
    fn test_bcm_non_cancellable() {
        let mut pm = BcmProgressManager::new();
        let id = pm.start("X", BcmProgressLocation::Window);
        pm.cancel(id);
        assert!(!pm.all_tasks()[0].cancelled); // not cancellable
    }
}


// --- bcn_: Editor tree view widget model ---

/// A tree node.
#[derive(Debug, Clone)]
pub struct BcnTreeNode {
    pub id: String,
    pub label: String,
    pub icon: Option<char>,
    pub collapsible: bool,
    pub expanded: bool,
    pub children: Vec<BcnTreeNode>,
    pub context_value: Option<String>,
    pub tooltip: Option<String>,
}

impl BcnTreeNode {
    pub fn leaf(id: &str, label: &str) -> Self {
        Self { id: id.to_string(), label: label.to_string(), icon: None, collapsible: false, expanded: false, children: Vec::new(), context_value: None, tooltip: None }
    }

    pub fn branch(id: &str, label: &str, children: Vec<BcnTreeNode>) -> Self {
        Self { id: id.to_string(), label: label.to_string(), icon: None, collapsible: true, expanded: false, children, context_value: None, tooltip: None }
    }

    pub fn with_icon(mut self, icon: char) -> Self { self.icon = Some(icon); self }

    pub fn toggle(&mut self) { if self.collapsible { self.expanded = !self.expanded; } }

    pub fn flatten(&self, depth: usize) -> Vec<(usize, &BcnTreeNode)> {
        let mut result = vec![(depth, self)];
        if self.expanded {
            for child in &self.children {
                result.extend(child.flatten(depth + 1));
            }
        }
        result
    }

    pub fn find(&self, id: &str) -> Option<&BcnTreeNode> {
        if self.id == id { return Some(self); }
        for child in &self.children {
            if let Some(found) = child.find(id) { return Some(found); }
        }
        None
    }

    pub fn find_mut(&mut self, id: &str) -> Option<&mut BcnTreeNode> {
        if self.id == id { return Some(self); }
        for child in &mut self.children {
            if let Some(found) = child.find_mut(id) { return Some(found); }
        }
        None
    }

    pub fn total_count(&self) -> usize {
        1 + self.children.iter().map(|c| c.total_count()).sum::<usize>()
    }
}

/// A tree view with cursor and selection.
#[derive(Debug)]
pub struct BcnTreeView {
    roots: Vec<BcnTreeNode>,
    cursor: usize,
    filter: String,
    view_id: String,
}

impl BcnTreeView {
    pub fn new(view_id: &str) -> Self {
        Self { roots: Vec::new(), cursor: 0, filter: String::new(), view_id: view_id.to_string() }
    }

    pub fn set_roots(&mut self, roots: Vec<BcnTreeNode>) { self.roots = roots; self.cursor = 0; }

    pub fn visible_nodes(&self) -> Vec<(usize, &BcnTreeNode)> {
        let mut nodes = Vec::new();
        for root in &self.roots { nodes.extend(root.flatten(0)); }
        if self.filter.is_empty() { nodes }
        else { let f = self.filter.to_lowercase(); nodes.into_iter().filter(|(_, n)| n.label.to_lowercase().contains(&f)).collect() }
    }

    pub fn cursor_node(&self) -> Option<&BcnTreeNode> { self.visible_nodes().get(self.cursor).map(|(_, n)| *n) }

    pub fn move_cursor(&mut self, delta: i32) {
        let count = self.visible_nodes().len();
        if count == 0 { return; }
        self.cursor = ((self.cursor as i32 + delta).rem_euclid(count as i32)) as usize;
    }

    pub fn toggle_at_cursor(&mut self) {
        if let Some(id) = self.cursor_node().map(|n| n.id.clone()) {
            for root in &mut self.roots {
                if let Some(node) = root.find_mut(&id) { node.toggle(); break; }
            }
        }
    }

    pub fn set_filter(&mut self, f: &str) { self.filter = f.to_string(); self.cursor = 0; }
    pub fn view_id(&self) -> &str { &self.view_id }
    pub fn total_nodes(&self) -> usize { self.roots.iter().map(|r| r.total_count()).sum() }

    pub fn render_lines(&self) -> Vec<String> {
        self.visible_nodes().iter().enumerate().map(|(i, (depth, node))| {
            let indent = "  ".repeat(*depth);
            let arrow = if node.collapsible { if node.expanded { "▾ " } else { "▸ " } } else { "  " };
            let icon = node.icon.map(|c| format!("{} ", c)).unwrap_or_default();
            let cursor = if i == self.cursor { "› " } else { "  " };
            format!("{}{}{}{}{}", cursor, indent, arrow, icon, node.label)
        }).collect()
    }
}

#[cfg(test)]
mod bcn_tests {
    use super::*;

    #[test]
    fn test_bcn_leaf() {
        let n = BcnTreeNode::leaf("f1", "file.rs");
        assert!(!n.collapsible);
        assert_eq!(n.total_count(), 1);
    }

    #[test]
    fn test_bcn_branch() {
        let n = BcnTreeNode::branch("d1", "src", vec![BcnTreeNode::leaf("f1", "main.rs")]);
        assert!(n.collapsible);
        assert_eq!(n.total_count(), 2);
    }

    #[test]
    fn test_bcn_flatten() {
        let mut n = BcnTreeNode::branch("d", "dir", vec![BcnTreeNode::leaf("f", "file")]);
        n.expanded = true;
        let flat = n.flatten(0);
        assert_eq!(flat.len(), 2);
        assert_eq!(flat[1].0, 1); // child at depth 1
    }

    #[test]
    fn test_bcn_find() {
        let n = BcnTreeNode::branch("d", "dir", vec![BcnTreeNode::leaf("f", "file")]);
        assert!(n.find("f").is_some());
        assert!(n.find("missing").is_none());
    }

    #[test]
    fn test_bcn_toggle() {
        let mut n = BcnTreeNode::branch("d", "dir", vec![]);
        assert!(!n.expanded);
        n.toggle();
        assert!(n.expanded);
    }

    #[test]
    fn test_bcn_tree_view() {
        let mut tv = BcnTreeView::new("fileExplorer");
        tv.set_roots(vec![BcnTreeNode::leaf("f", "main.rs")]);
        assert_eq!(tv.visible_nodes().len(), 1);
    }

    #[test]
    fn test_bcn_cursor_move() {
        let mut tv = BcnTreeView::new("test");
        tv.set_roots(vec![BcnTreeNode::leaf("a", "A"), BcnTreeNode::leaf("b", "B")]);
        tv.move_cursor(1);
        assert_eq!(tv.cursor_node().unwrap().id, "b");
    }

    #[test]
    fn test_bcn_filter() {
        let mut tv = BcnTreeView::new("test");
        tv.set_roots(vec![BcnTreeNode::leaf("a", "Alpha"), BcnTreeNode::leaf("b", "Beta")]);
        tv.set_filter("alpha");
        assert_eq!(tv.visible_nodes().len(), 1);
    }

    #[test]
    fn test_bcn_render() {
        let mut tv = BcnTreeView::new("test");
        tv.set_roots(vec![BcnTreeNode::leaf("f", "file.rs").with_icon('📄')]);
        let lines = tv.render_lines();
        assert!(lines[0].contains("📄"));
    }

    #[test]
    fn test_bcn_total_nodes() {
        let mut tv = BcnTreeView::new("test");
        tv.set_roots(vec![BcnTreeNode::branch("d", "dir", vec![BcnTreeNode::leaf("f", "f")])]);
        assert_eq!(tv.total_nodes(), 2);
    }
}


// --- bco_: Editor webview panel model ---

/// Webview content security options.
#[derive(Debug, Clone)]
pub struct BcoContentSecurity {
    pub allow_scripts: bool,
    pub allow_forms: bool,
    pub local_resource_roots: Vec<String>,
}

impl BcoContentSecurity {
    pub fn default_policy() -> Self { Self { allow_scripts: false, allow_forms: false, local_resource_roots: Vec::new() } }
    pub fn with_scripts(mut self) -> Self { self.allow_scripts = true; self }
}

/// A webview panel state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BcoWebviewState { Active, Visible, Hidden, Disposed }

/// Message between extension and webview.
#[derive(Debug, Clone)]
pub struct BcoWebviewMessage {
    pub command: String,
    pub payload: String,
}

impl BcoWebviewMessage {
    pub fn new(cmd: &str, payload: &str) -> Self { Self { command: cmd.to_string(), payload: payload.to_string() } }
}

/// A webview panel.
#[derive(Debug)]
pub struct BcoWebviewPanel {
    pub id: String,
    pub view_type: String,
    pub title: String,
    pub html: String,
    pub state: BcoWebviewState,
    pub security: BcoContentSecurity,
    pub retain_context: bool,
    inbox: Vec<BcoWebviewMessage>,
    outbox: Vec<BcoWebviewMessage>,
}

impl BcoWebviewPanel {
    pub fn new(id: &str, view_type: &str, title: &str) -> Self {
        Self { id: id.to_string(), view_type: view_type.to_string(), title: title.to_string(), html: String::new(), state: BcoWebviewState::Active, security: BcoContentSecurity::default_policy(), retain_context: false, inbox: Vec::new(), outbox: Vec::new() }
    }

    pub fn set_html(&mut self, html: &str) { self.html = html.to_string(); }
    pub fn set_title(&mut self, t: &str) { self.title = t.to_string(); }

    pub fn post_message(&mut self, msg: BcoWebviewMessage) { self.outbox.push(msg); }
    pub fn receive_message(&mut self, msg: BcoWebviewMessage) { self.inbox.push(msg); }

    pub fn drain_outbox(&mut self) -> Vec<BcoWebviewMessage> { self.outbox.drain(..).collect() }
    pub fn drain_inbox(&mut self) -> Vec<BcoWebviewMessage> { self.inbox.drain(..).collect() }

    pub fn reveal(&mut self) { self.state = BcoWebviewState::Active; }
    pub fn hide(&mut self) { self.state = BcoWebviewState::Hidden; }
    pub fn dispose(&mut self) { self.state = BcoWebviewState::Disposed; }

    pub fn is_active(&self) -> bool { self.state == BcoWebviewState::Active }
    pub fn is_disposed(&self) -> bool { self.state == BcoWebviewState::Disposed }
}

/// Manages all webview panels.
#[derive(Debug)]
pub struct BcoWebviewManager {
    panels: Vec<BcoWebviewPanel>,
}

impl BcoWebviewManager {
    pub fn new() -> Self { Self { panels: Vec::new() } }

    pub fn create_panel(&mut self, id: &str, view_type: &str, title: &str) -> &mut BcoWebviewPanel {
        self.panels.push(BcoWebviewPanel::new(id, view_type, title));
        self.panels.last_mut().unwrap()
    }

    pub fn get_panel(&self, id: &str) -> Option<&BcoWebviewPanel> { self.panels.iter().find(|p| p.id == id) }
    pub fn get_panel_mut(&mut self, id: &str) -> Option<&mut BcoWebviewPanel> { self.panels.iter_mut().find(|p| p.id == id) }

    pub fn active_panels(&self) -> Vec<&BcoWebviewPanel> { self.panels.iter().filter(|p| !p.is_disposed()).collect() }
    pub fn panel_count(&self) -> usize { self.panels.len() }

    pub fn dispose_panel(&mut self, id: &str) {
        if let Some(p) = self.panels.iter_mut().find(|p| p.id == id) { p.dispose(); }
    }

    pub fn cleanup(&mut self) { self.panels.retain(|p| !p.is_disposed()); }
}

#[cfg(test)]
mod bco_tests {
    use super::*;

    #[test]
    fn test_bco_panel_new() {
        let p = BcoWebviewPanel::new("p1", "preview", "Preview");
        assert!(p.is_active());
        assert_eq!(p.title, "Preview");
    }

    #[test]
    fn test_bco_html() {
        let mut p = BcoWebviewPanel::new("p1", "preview", "Preview");
        p.set_html("<h1>Hello</h1>");
        assert!(p.html.contains("Hello"));
    }

    #[test]
    fn test_bco_messaging() {
        let mut p = BcoWebviewPanel::new("p1", "t", "T");
        p.post_message(BcoWebviewMessage::new("update", "{}"));
        let out = p.drain_outbox();
        assert_eq!(out.len(), 1);
        assert!(p.drain_outbox().is_empty());
    }

    #[test]
    fn test_bco_lifecycle() {
        let mut p = BcoWebviewPanel::new("p1", "t", "T");
        p.hide();
        assert_eq!(p.state, BcoWebviewState::Hidden);
        p.reveal();
        assert!(p.is_active());
        p.dispose();
        assert!(p.is_disposed());
    }

    #[test]
    fn test_bco_security() {
        let s = BcoContentSecurity::default_policy().with_scripts();
        assert!(s.allow_scripts);
    }

    #[test]
    fn test_bco_manager() {
        let mut mgr = BcoWebviewManager::new();
        mgr.create_panel("p1", "markdown", "Preview");
        assert_eq!(mgr.panel_count(), 1);
        assert!(mgr.get_panel("p1").is_some());
    }

    #[test]
    fn test_bco_dispose() {
        let mut mgr = BcoWebviewManager::new();
        mgr.create_panel("p1", "t", "T");
        mgr.dispose_panel("p1");
        assert_eq!(mgr.active_panels().len(), 0);
    }

    #[test]
    fn test_bco_cleanup() {
        let mut mgr = BcoWebviewManager::new();
        mgr.create_panel("p1", "t", "T");
        mgr.dispose_panel("p1");
        mgr.cleanup();
        assert_eq!(mgr.panel_count(), 0);
    }

    #[test]
    fn test_bco_retain() {
        let mut p = BcoWebviewPanel::new("p1", "t", "T");
        p.retain_context = true;
        assert!(p.retain_context);
    }

    #[test]
    fn test_bco_inbox() {
        let mut p = BcoWebviewPanel::new("p1", "t", "T");
        p.receive_message(BcoWebviewMessage::new("click", "btn1"));
        let msgs = p.drain_inbox();
        assert_eq!(msgs.len(), 1);
        assert_eq!(msgs[0].command, "click");
    }
}


// --- bcp_: Editor output channel model ---

/// Log level for output channel messages.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum BcpLogLevel { Trace, Debug, Info, Warning, Error }

/// A single output line.
#[derive(Debug, Clone)]
pub struct BcpOutputLine {
    pub text: String,
    pub level: BcpLogLevel,
    pub timestamp: u64,
}

/// An output channel.
#[derive(Debug)]
pub struct BcpOutputChannel {
    pub name: String,
    pub language_id: Option<String>,
    lines: Vec<BcpOutputLine>,
    visible: bool,
    min_level: BcpLogLevel,
    preserved_focus: bool,
}

impl BcpOutputChannel {
    pub fn new(name: &str) -> Self {
        Self { name: name.to_string(), language_id: None, lines: Vec::new(), visible: false, min_level: BcpLogLevel::Info, preserved_focus: false }
    }

    pub fn log(name: &str, language_id: &str) -> Self {
        Self { name: name.to_string(), language_id: Some(language_id.to_string()), lines: Vec::new(), visible: false, min_level: BcpLogLevel::Info, preserved_focus: false }
    }

    pub fn append(&mut self, text: &str, level: BcpLogLevel) {
        self.lines.push(BcpOutputLine { text: text.to_string(), level, timestamp: 0 });
    }

    pub fn append_line(&mut self, text: &str) { self.append(text, BcpLogLevel::Info); }

    pub fn info(&mut self, text: &str) { self.append(text, BcpLogLevel::Info); }
    pub fn warn(&mut self, text: &str) { self.append(text, BcpLogLevel::Warning); }
    pub fn error(&mut self, text: &str) { self.append(text, BcpLogLevel::Error); }
    pub fn trace(&mut self, text: &str) { self.append(text, BcpLogLevel::Trace); }
    pub fn debug(&mut self, text: &str) { self.append(text, BcpLogLevel::Debug); }

    pub fn clear(&mut self) { self.lines.clear(); }
    pub fn show(&mut self, preserve_focus: bool) { self.visible = true; self.preserved_focus = preserve_focus; }
    pub fn hide(&mut self) { self.visible = false; }
    pub fn is_visible(&self) -> bool { self.visible }

    pub fn set_min_level(&mut self, level: BcpLogLevel) { self.min_level = level; }

    pub fn filtered_lines(&self) -> Vec<&BcpOutputLine> {
        self.lines.iter().filter(|l| l.level >= self.min_level).collect()
    }

    pub fn line_count(&self) -> usize { self.lines.len() }

    pub fn render(&self, max_lines: usize) -> Vec<String> {
        let filtered = self.filtered_lines();
        let skip = filtered.len().saturating_sub(max_lines);
        filtered.iter().skip(skip).map(|l| {
            let prefix = match l.level {
                BcpLogLevel::Error => "[ERR]",
                BcpLogLevel::Warning => "[WRN]",
                BcpLogLevel::Info => "[INF]",
                BcpLogLevel::Debug => "[DBG]",
                BcpLogLevel::Trace => "[TRC]",
            };
            format!("{} {}", prefix, l.text)
        }).collect()
    }
}

/// Manages multiple output channels.
#[derive(Debug)]
pub struct BcpOutputManager {
    channels: Vec<BcpOutputChannel>,
    active: Option<String>,
}

impl BcpOutputManager {
    pub fn new() -> Self { Self { channels: Vec::new(), active: None } }

    pub fn create_channel(&mut self, name: &str) -> &mut BcpOutputChannel {
        self.channels.push(BcpOutputChannel::new(name));
        self.channels.last_mut().unwrap()
    }

    pub fn get_channel(&self, name: &str) -> Option<&BcpOutputChannel> { self.channels.iter().find(|c| c.name == name) }
    pub fn get_channel_mut(&mut self, name: &str) -> Option<&mut BcpOutputChannel> { self.channels.iter_mut().find(|c| c.name == name) }

    pub fn channel_names(&self) -> Vec<&str> { self.channels.iter().map(|c| c.name.as_str()).collect() }
    pub fn set_active(&mut self, name: &str) { self.active = Some(name.to_string()); }
    pub fn active_channel(&self) -> Option<&BcpOutputChannel> { self.active.as_ref().and_then(|n| self.get_channel(n)) }
}

