// --- bdp_: Editor hover information model ---

/// Hover content type.
#[derive(Debug, Clone)]
pub enum BdpHoverContent {
    PlainText(String),
    Markdown(String),
    CodeBlock { language: String, code: String },
}

impl BdpHoverContent {
    pub fn plain(text: &str) -> Self { BdpHoverContent::PlainText(text.to_string()) }
    pub fn markdown(text: &str) -> Self { BdpHoverContent::Markdown(text.to_string()) }
    pub fn code(lang: &str, code: &str) -> Self { BdpHoverContent::CodeBlock { language: lang.to_string(), code: code.to_string() } }

    pub fn render(&self) -> Vec<String> {
        match self {
            BdpHoverContent::PlainText(t) => t.lines().map(String::from).collect(),
            BdpHoverContent::Markdown(t) => t.lines().map(String::from).collect(),
            BdpHoverContent::CodeBlock { language, code } => {
                let mut lines = vec![format!("```{}", language)];
                lines.extend(code.lines().map(String::from));
                lines.push("```".to_string());
                lines
            }
        }
    }
}

/// A hover result.
#[derive(Debug)]
pub struct BdpHover {
    pub contents: Vec<BdpHoverContent>,
    pub range_line: u32,
    pub range_start: u32,
    pub range_end: u32,
}

impl BdpHover {
    pub fn new(line: u32, start: u32, end: u32) -> Self {
        Self { contents: Vec::new(), range_line: line, range_start: start, range_end: end }
    }

    pub fn add_content(&mut self, c: BdpHoverContent) { self.contents.push(c); }

    pub fn render(&self) -> Vec<String> {
        let mut lines = Vec::new();
        for (i, content) in self.contents.iter().enumerate() {
            if i > 0 { lines.push("─".repeat(40)); }
            lines.extend(content.render());
        }
        lines
    }

    pub fn is_empty(&self) -> bool { self.contents.is_empty() }
}

/// Hover widget state.
#[derive(Debug)]
pub struct BdpHoverWidget {
    hover: Option<BdpHover>,
    visible: bool,
    pinned: bool,
    scroll_offset: usize,
}

impl BdpHoverWidget {
    pub fn new() -> Self { Self { hover: None, visible: false, pinned: false, scroll_offset: 0 } }

    pub fn show(&mut self, hover: BdpHover) { self.hover = Some(hover); self.visible = true; self.scroll_offset = 0; }
    pub fn hide(&mut self) { if !self.pinned { self.visible = false; } }
    pub fn force_hide(&mut self) { self.visible = false; self.pinned = false; }
    pub fn is_visible(&self) -> bool { self.visible }
    pub fn toggle_pin(&mut self) { self.pinned = !self.pinned; }
    pub fn is_pinned(&self) -> bool { self.pinned }

    pub fn scroll(&mut self, delta: i32) { self.scroll_offset = (self.scroll_offset as i32 + delta).max(0) as usize; }

    pub fn render(&self, max_lines: usize) -> Vec<String> {
        if !self.visible { return Vec::new(); }
        match &self.hover {
            Some(h) => {
                let all = h.render();
                let skip = self.scroll_offset.min(all.len().saturating_sub(max_lines));
                all.into_iter().skip(skip).take(max_lines).collect()
            }
            None => Vec::new(),
        }
    }
}

#[cfg(test)]
mod bdp_tests {
    use super::*;

    #[test]
    fn test_bdp_plain() {
        let c = BdpHoverContent::plain("hello");
        assert_eq!(c.render(), vec!["hello"]);
    }

    #[test]
    fn test_bdp_code_block() {
        let c = BdpHoverContent::code("rust", "fn main() {}");
        let lines = c.render();
        assert!(lines[0].contains("```rust"));
    }

    #[test]
    fn test_bdp_hover() {
        let mut h = BdpHover::new(5, 0, 10);
        h.add_content(BdpHoverContent::plain("Type: i32"));
        assert!(!h.is_empty());
        assert_eq!(h.render().len(), 1);
    }

    #[test]
    fn test_bdp_hover_multi() {
        let mut h = BdpHover::new(1, 0, 5);
        h.add_content(BdpHoverContent::plain("docs"));
        h.add_content(BdpHoverContent::code("rust", "fn x()"));
        let lines = h.render();
        assert!(lines.len() >= 3); // docs + separator + code block
    }

    #[test]
    fn test_bdp_widget_show() {
        let mut w = BdpHoverWidget::new();
        let mut h = BdpHover::new(1, 0, 5);
        h.add_content(BdpHoverContent::plain("info"));
        w.show(h);
        assert!(w.is_visible());
    }

    #[test]
    fn test_bdp_widget_hide() {
        let mut w = BdpHoverWidget::new();
        w.show(BdpHover::new(1, 0, 5));
        w.hide();
        assert!(!w.is_visible());
    }

    #[test]
    fn test_bdp_pin() {
        let mut w = BdpHoverWidget::new();
        w.show(BdpHover::new(1, 0, 5));
        w.toggle_pin();
        assert!(w.is_pinned());
        w.hide(); // pinned, won't hide
        assert!(w.is_visible());
        w.force_hide();
        assert!(!w.is_visible());
    }

    #[test]
    fn test_bdp_scroll() {
        let mut w = BdpHoverWidget::new();
        let mut h = BdpHover::new(1, 0, 5);
        for i in 0..20 { h.add_content(BdpHoverContent::plain(&format!("line {}", i))); }
        w.show(h);
        w.scroll(5);
        let lines = w.render(3);
        assert_eq!(lines.len(), 3);
    }

    #[test]
    fn test_bdp_empty_hover() {
        let h = BdpHover::new(0, 0, 0);
        assert!(h.is_empty());
    }

    #[test]
    fn test_bdp_widget_empty() {
        let w = BdpHoverWidget::new();
        assert!(w.render(10).is_empty());
    }
}

// bdq_: Document formatting model — format document, format selection,
// format on type, format on paste, formatter provider priority

/// Formatter kind (document vs range vs on-type)
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BdqFormatterKind {
    Document,
    Range,
    OnType,
    OnPaste,
}

/// A single text edit from a formatter
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BdqFormatEdit {
    pub start_line: usize,
    pub start_col: usize,
    pub end_line: usize,
    pub end_col: usize,
    pub new_text: String,
}

impl BdqFormatEdit {
    pub fn new(sl: usize, sc: usize, el: usize, ec: usize, text: &str) -> Self {
        Self { start_line: sl, start_col: sc, end_line: el, end_col: ec, new_text: text.to_string() }
    }

    pub fn is_insert(&self) -> bool {
        self.start_line == self.end_line && self.start_col == self.end_col
    }

    pub fn is_delete(&self) -> bool {
        self.new_text.is_empty()
    }

    pub fn span_lines(&self) -> usize {
        self.end_line.saturating_sub(self.start_line) + 1
    }
}

/// Formatter provider with priority
#[derive(Debug, Clone)]
pub struct BdqFormatterProvider {
    pub id: String,
    pub display_name: String,
    pub kind: BdqFormatterKind,
    pub priority: i32,
    pub language_ids: Vec<String>,
}

impl BdqFormatterProvider {
    pub fn new(id: &str, name: &str, kind: BdqFormatterKind, priority: i32) -> Self {
        Self {
            id: id.to_string(),
            display_name: name.to_string(),
            kind,
            priority,
            language_ids: Vec::new(),
        }
    }

    pub fn with_language(mut self, lang: &str) -> Self {
        self.language_ids.push(lang.to_string());
        self
    }

    pub fn supports_language(&self, lang: &str) -> bool {
        self.language_ids.is_empty() || self.language_ids.iter().any(|l| l == lang)
    }
}

/// Format request targeting whole document or a range
#[derive(Debug, Clone)]
pub struct BdqFormatRequest {
    pub kind: BdqFormatterKind,
    pub range_start: Option<(usize, usize)>,
    pub range_end: Option<(usize, usize)>,
    pub trigger_char: Option<char>,
    pub tab_size: usize,
    pub insert_spaces: bool,
}

impl BdqFormatRequest {
    pub fn document(tab_size: usize, insert_spaces: bool) -> Self {
        Self {
            kind: BdqFormatterKind::Document,
            range_start: None,
            range_end: None,
            trigger_char: None,
            tab_size,
            insert_spaces,
        }
    }

    pub fn range(sl: usize, sc: usize, el: usize, ec: usize, tab_size: usize, insert_spaces: bool) -> Self {
        Self {
            kind: BdqFormatterKind::Range,
            range_start: Some((sl, sc)),
            range_end: Some((el, ec)),
            trigger_char: None,
            tab_size,
            insert_spaces,
        }
    }

    pub fn on_type(ch: char, tab_size: usize, insert_spaces: bool) -> Self {
        Self {
            kind: BdqFormatterKind::OnType,
            range_start: None,
            range_end: None,
            trigger_char: Some(ch),
            tab_size,
            insert_spaces,
        }
    }

    pub fn on_paste(sl: usize, sc: usize, el: usize, ec: usize, tab_size: usize, insert_spaces: bool) -> Self {
        Self {
            kind: BdqFormatterKind::OnPaste,
            range_start: Some((sl, sc)),
            range_end: Some((el, ec)),
            trigger_char: None,
            tab_size,
            insert_spaces,
        }
    }

    pub fn is_whole_document(&self) -> bool {
        self.range_start.is_none() && self.range_end.is_none()
    }

    pub fn indent_string(&self) -> String {
        if self.insert_spaces {
            " ".repeat(self.tab_size)
        } else {
            "\t".to_string()
        }
    }
}

/// Format result containing edits
#[derive(Debug, Clone)]
pub struct BdqFormatResult {
    pub edits: Vec<BdqFormatEdit>,
    pub provider_id: String,
    pub elapsed_ms: u64,
}

impl BdqFormatResult {
    pub fn new(provider_id: &str) -> Self {
        Self { edits: Vec::new(), provider_id: provider_id.to_string(), elapsed_ms: 0 }
    }

    pub fn with_edit(mut self, edit: BdqFormatEdit) -> Self {
        self.edits.push(edit);
        self
    }

    pub fn edit_count(&self) -> usize {
        self.edits.len()
    }

    pub fn has_edits(&self) -> bool {
        !self.edits.is_empty()
    }

    pub fn lines_affected(&self) -> usize {
        let mut lines = std::collections::HashSet::new();
        for e in &self.edits {
            for l in e.start_line..=e.end_line {
                lines.insert(l);
            }
        }
        lines.len()
    }

    pub fn sorted_edits(&self) -> Vec<&BdqFormatEdit> {
        let mut sorted: Vec<&BdqFormatEdit> = self.edits.iter().collect();
        sorted.sort_by(|a, b| {
            a.start_line.cmp(&b.start_line).then(a.start_col.cmp(&b.start_col))
        });
        sorted
    }
}

/// Registry of formatter providers
#[derive(Debug, Clone, Default)]
pub struct BdqFormatterRegistry {
    pub providers: Vec<BdqFormatterProvider>,
}

impl BdqFormatterRegistry {
    pub fn new() -> Self {
        Self { providers: Vec::new() }
    }

    pub fn register(&mut self, provider: BdqFormatterProvider) {
        self.providers.push(provider);
    }

    pub fn unregister(&mut self, id: &str) -> bool {
        let before = self.providers.len();
        self.providers.retain(|p| p.id != id);
        self.providers.len() < before
    }

    pub fn find_for_language(&self, lang: &str, kind: BdqFormatterKind) -> Vec<&BdqFormatterProvider> {
        let mut matching: Vec<&BdqFormatterProvider> = self.providers.iter()
            .filter(|p| p.kind == kind && p.supports_language(lang))
            .collect();
        matching.sort_by(|a, b| b.priority.cmp(&a.priority));
        matching
    }

    pub fn best_for_language(&self, lang: &str, kind: BdqFormatterKind) -> Option<&BdqFormatterProvider> {
        self.find_for_language(lang, kind).into_iter().next()
    }

    pub fn provider_count(&self) -> usize {
        self.providers.len()
    }
}

#[cfg(test)]
mod tests_bdq {
    use super::*;

    #[test]
    fn test_bdq_format_edit_insert() {
        let edit = BdqFormatEdit::new(0, 0, 0, 0, "hello");
        assert!(edit.is_insert());
        assert!(!edit.is_delete());
        assert_eq!(edit.span_lines(), 1);
    }

    #[test]
    fn test_bdq_format_edit_delete() {
        let edit = BdqFormatEdit::new(1, 0, 3, 10, "");
        assert!(!edit.is_insert());
        assert!(edit.is_delete());
        assert_eq!(edit.span_lines(), 3);
    }

    #[test]
    fn test_bdq_formatter_provider() {
        let p = BdqFormatterProvider::new("prettier", "Prettier", BdqFormatterKind::Document, 10)
            .with_language("javascript")
            .with_language("typescript");
        assert!(p.supports_language("javascript"));
        assert!(!p.supports_language("rust"));
    }

    #[test]
    fn test_bdq_format_request_document() {
        let req = BdqFormatRequest::document(4, true);
        assert!(req.is_whole_document());
        assert_eq!(req.indent_string(), "    ");
    }

    #[test]
    fn test_bdq_format_request_range() {
        let req = BdqFormatRequest::range(5, 0, 10, 20, 2, false);
        assert!(!req.is_whole_document());
        assert_eq!(req.indent_string(), "\t");
    }

    #[test]
    fn test_bdq_format_request_on_type() {
        let req = BdqFormatRequest::on_type(';', 4, true);
        assert_eq!(req.trigger_char, Some(';'));
    }

    #[test]
    fn test_bdq_format_request_on_paste() {
        let req = BdqFormatRequest::on_paste(0, 0, 5, 0, 4, true);
        assert!(!req.is_whole_document());
        assert_eq!(req.kind, BdqFormatterKind::OnPaste);
    }

    #[test]
    fn test_bdq_format_result() {
        let result = BdqFormatResult::new("prettier")
            .with_edit(BdqFormatEdit::new(1, 0, 1, 10, "  formatted"))
            .with_edit(BdqFormatEdit::new(3, 0, 4, 5, "  also"));
        assert_eq!(result.edit_count(), 2);
        assert!(result.has_edits());
        assert_eq!(result.lines_affected(), 3);
    }

    #[test]
    fn test_bdq_format_result_sorted() {
        let result = BdqFormatResult::new("test")
            .with_edit(BdqFormatEdit::new(5, 0, 5, 10, "b"))
            .with_edit(BdqFormatEdit::new(1, 0, 1, 10, "a"));
        let sorted = result.sorted_edits();
        assert_eq!(sorted[0].start_line, 1);
        assert_eq!(sorted[1].start_line, 5);
    }

    #[test]
    fn test_bdq_registry() {
        let mut reg = BdqFormatterRegistry::new();
        reg.register(BdqFormatterProvider::new("prettier", "Prettier", BdqFormatterKind::Document, 10)
            .with_language("javascript"));
        reg.register(BdqFormatterProvider::new("biome", "Biome", BdqFormatterKind::Document, 20)
            .with_language("javascript"));
        reg.register(BdqFormatterProvider::new("rustfmt", "Rustfmt", BdqFormatterKind::Document, 10)
            .with_language("rust"));
        assert_eq!(reg.provider_count(), 3);
        let js = reg.find_for_language("javascript", BdqFormatterKind::Document);
        assert_eq!(js.len(), 2);
        assert_eq!(js[0].id, "biome"); // higher priority
        let best = reg.best_for_language("rust", BdqFormatterKind::Document).unwrap();
        assert_eq!(best.id, "rustfmt");
        assert!(reg.unregister("prettier"));
        assert_eq!(reg.provider_count(), 2);
    }
}

// bdr_: Selection highlight model — highlight occurrences of selection,
// word highlight, text selection ranges, highlight decorations

/// Kind of selection highlight
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BdrHighlightKind {
    Selection,
    WordUnderCursor,
    FindMatch,
    BracketMatch,
    LineHighlight,
    ColumnHighlight,
}

/// A highlighted range in the editor
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BdrHighlightRange {
    pub start_line: usize,
    pub start_col: usize,
    pub end_line: usize,
    pub end_col: usize,
    pub kind: BdrHighlightKind,
    pub whole_line: bool,
}

impl BdrHighlightRange {
    pub fn new(sl: usize, sc: usize, el: usize, ec: usize, kind: BdrHighlightKind) -> Self {
        Self { start_line: sl, start_col: sc, end_line: el, end_col: ec, kind, whole_line: false }
    }

    pub fn line(line: usize, kind: BdrHighlightKind) -> Self {
        Self { start_line: line, start_col: 0, end_line: line, end_col: usize::MAX, kind, whole_line: true }
    }

    pub fn is_single_line(&self) -> bool {
        self.start_line == self.end_line
    }

    pub fn contains_position(&self, line: usize, col: usize) -> bool {
        if line < self.start_line || line > self.end_line { return false; }
        if line == self.start_line && col < self.start_col { return false; }
        if line == self.end_line && col > self.end_col { return false; }
        true
    }

    pub fn overlaps(&self, other: &BdrHighlightRange) -> bool {
        !(self.end_line < other.start_line
            || other.end_line < self.start_line
            || (self.end_line == other.start_line && self.end_col < other.start_col)
            || (other.end_line == self.start_line && other.end_col < self.start_col))
    }

    pub fn line_count(&self) -> usize {
        self.end_line - self.start_line + 1
    }
}

/// Selection highlight configuration
#[derive(Debug, Clone)]
pub struct BdrHighlightConfig {
    pub highlight_selections: bool,
    pub highlight_word: bool,
    pub highlight_find_matches: bool,
    pub highlight_brackets: bool,
    pub highlight_current_line: bool,
    pub selection_highlight_color: String,
    pub word_highlight_color: String,
    pub find_match_color: String,
    pub min_selection_length: usize,
    pub max_highlights: usize,
}

impl Default for BdrHighlightConfig {
    fn default() -> Self {
        Self {
            highlight_selections: true,
            highlight_word: true,
            highlight_find_matches: true,
            highlight_brackets: true,
            highlight_current_line: true,
            selection_highlight_color: "#add6ff26".to_string(),
            word_highlight_color: "#57575740".to_string(),
            find_match_color: "#ea5c0055".to_string(),
            min_selection_length: 1,
            max_highlights: 500,
        }
    }
}

impl BdrHighlightConfig {
    pub fn color_for_kind(&self, kind: BdrHighlightKind) -> &str {
        match kind {
            BdrHighlightKind::Selection => &self.selection_highlight_color,
            BdrHighlightKind::WordUnderCursor => &self.word_highlight_color,
            BdrHighlightKind::FindMatch => &self.find_match_color,
            _ => &self.word_highlight_color,
        }
    }

    pub fn is_kind_enabled(&self, kind: BdrHighlightKind) -> bool {
        match kind {
            BdrHighlightKind::Selection => self.highlight_selections,
            BdrHighlightKind::WordUnderCursor => self.highlight_word,
            BdrHighlightKind::FindMatch => self.highlight_find_matches,
            BdrHighlightKind::BracketMatch => self.highlight_brackets,
            BdrHighlightKind::LineHighlight => self.highlight_current_line,
            BdrHighlightKind::ColumnHighlight => true,
        }
    }
}

/// Manager for highlight ranges
#[derive(Debug, Clone, Default)]
pub struct BdrHighlightManager {
    pub ranges: Vec<BdrHighlightRange>,
    pub config: BdrHighlightConfig,
    pub selected_text: Option<String>,
}

impl BdrHighlightManager {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn set_selected_text(&mut self, text: Option<String>) {
        self.selected_text = text;
    }

    pub fn add_range(&mut self, range: BdrHighlightRange) {
        if self.ranges.len() < self.config.max_highlights && self.config.is_kind_enabled(range.kind) {
            self.ranges.push(range);
        }
    }

    pub fn clear_kind(&mut self, kind: BdrHighlightKind) {
        self.ranges.retain(|r| r.kind != kind);
    }

    pub fn clear_all(&mut self) {
        self.ranges.clear();
        self.selected_text = None;
    }

    pub fn ranges_for_line(&self, line: usize) -> Vec<&BdrHighlightRange> {
        self.ranges.iter().filter(|r| line >= r.start_line && line <= r.end_line).collect()
    }

    pub fn ranges_of_kind(&self, kind: BdrHighlightKind) -> Vec<&BdrHighlightRange> {
        self.ranges.iter().filter(|r| r.kind == kind).collect()
    }

    pub fn count(&self) -> usize {
        self.ranges.len()
    }

    pub fn count_kind(&self, kind: BdrHighlightKind) -> usize {
        self.ranges.iter().filter(|r| r.kind == kind).count()
    }

    pub fn has_highlights_on_line(&self, line: usize) -> bool {
        self.ranges.iter().any(|r| line >= r.start_line && line <= r.end_line)
    }
}

#[cfg(test)]
mod tests_bdr {
    use super::*;

    #[test]
    fn test_bdr_highlight_range_basic() {
        let r = BdrHighlightRange::new(1, 5, 1, 10, BdrHighlightKind::Selection);
        assert!(r.is_single_line());
        assert_eq!(r.line_count(), 1);
        assert!(r.contains_position(1, 7));
        assert!(!r.contains_position(1, 11));
    }

    #[test]
    fn test_bdr_highlight_range_multiline() {
        let r = BdrHighlightRange::new(1, 0, 5, 20, BdrHighlightKind::FindMatch);
        assert!(!r.is_single_line());
        assert_eq!(r.line_count(), 5);
        assert!(r.contains_position(3, 0));
    }

    #[test]
    fn test_bdr_highlight_range_line() {
        let r = BdrHighlightRange::line(10, BdrHighlightKind::LineHighlight);
        assert!(r.whole_line);
        assert!(r.is_single_line());
    }

    #[test]
    fn test_bdr_highlight_range_overlaps() {
        let a = BdrHighlightRange::new(1, 0, 3, 10, BdrHighlightKind::Selection);
        let b = BdrHighlightRange::new(2, 5, 5, 0, BdrHighlightKind::FindMatch);
        let c = BdrHighlightRange::new(5, 0, 7, 0, BdrHighlightKind::Selection);
        assert!(a.overlaps(&b));
        assert!(!a.overlaps(&c));
    }

    #[test]
    fn test_bdr_config_defaults() {
        let cfg = BdrHighlightConfig::default();
        assert!(cfg.highlight_selections);
        assert!(cfg.highlight_word);
        assert_eq!(cfg.max_highlights, 500);
        assert!(cfg.is_kind_enabled(BdrHighlightKind::Selection));
    }

    #[test]
    fn test_bdr_config_color() {
        let cfg = BdrHighlightConfig::default();
        assert_eq!(cfg.color_for_kind(BdrHighlightKind::Selection), "#add6ff26");
        assert_eq!(cfg.color_for_kind(BdrHighlightKind::FindMatch), "#ea5c0055");
    }

    #[test]
    fn test_bdr_manager_add_clear() {
        let mut mgr = BdrHighlightManager::new();
        mgr.add_range(BdrHighlightRange::new(1, 0, 1, 5, BdrHighlightKind::Selection));
        mgr.add_range(BdrHighlightRange::new(3, 0, 3, 5, BdrHighlightKind::WordUnderCursor));
        assert_eq!(mgr.count(), 2);
        mgr.clear_kind(BdrHighlightKind::Selection);
        assert_eq!(mgr.count(), 1);
        assert_eq!(mgr.count_kind(BdrHighlightKind::WordUnderCursor), 1);
    }

    #[test]
    fn test_bdr_manager_line_query() {
        let mut mgr = BdrHighlightManager::new();
        mgr.add_range(BdrHighlightRange::new(5, 0, 5, 10, BdrHighlightKind::Selection));
        mgr.add_range(BdrHighlightRange::new(5, 15, 5, 20, BdrHighlightKind::FindMatch));
        assert_eq!(mgr.ranges_for_line(5).len(), 2);
        assert!(mgr.has_highlights_on_line(5));
        assert!(!mgr.has_highlights_on_line(6));
    }

    #[test]
    fn test_bdr_manager_selected_text() {
        let mut mgr = BdrHighlightManager::new();
        mgr.set_selected_text(Some("hello".to_string()));
        assert_eq!(mgr.selected_text.as_deref(), Some("hello"));
        mgr.clear_all();
        assert!(mgr.selected_text.is_none());
    }

    #[test]
    fn test_bdr_manager_max_highlights() {
        let mut mgr = BdrHighlightManager::new();
        mgr.config.max_highlights = 3;
        for i in 0..5 {
            mgr.add_range(BdrHighlightRange::new(i, 0, i, 5, BdrHighlightKind::Selection));
        }
        assert_eq!(mgr.count(), 3);
    }
}

// bds_: Document highlight model — word highlight, symbol references,
// read/write access highlighting, semantic highlighting triggers

/// Document highlight access kind
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BdsHighlightAccess {
    Read,
    Write,
    Text,
}

/// A document highlight occurrence
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BdsDocumentHighlight {
    pub start_line: usize,
    pub start_col: usize,
    pub end_line: usize,
    pub end_col: usize,
    pub access: BdsHighlightAccess,
}

impl BdsDocumentHighlight {
    pub fn new(sl: usize, sc: usize, el: usize, ec: usize, access: BdsHighlightAccess) -> Self {
        Self { start_line: sl, start_col: sc, end_line: el, end_col: ec, access }
    }

    pub fn read(sl: usize, sc: usize, el: usize, ec: usize) -> Self {
        Self::new(sl, sc, el, ec, BdsHighlightAccess::Read)
    }

    pub fn write(sl: usize, sc: usize, el: usize, ec: usize) -> Self {
        Self::new(sl, sc, el, ec, BdsHighlightAccess::Write)
    }

    pub fn text(sl: usize, sc: usize, el: usize, ec: usize) -> Self {
        Self::new(sl, sc, el, ec, BdsHighlightAccess::Text)
    }

    pub fn is_read(&self) -> bool { self.access == BdsHighlightAccess::Read }
    pub fn is_write(&self) -> bool { self.access == BdsHighlightAccess::Write }

    pub fn contains_position(&self, line: usize, col: usize) -> bool {
        if line < self.start_line || line > self.end_line { return false; }
        if line == self.start_line && col < self.start_col { return false; }
        if line == self.end_line && col > self.end_col { return false; }
        true
    }
}

/// Trigger for document highlights
#[derive(Debug, Clone)]
pub struct BdsHighlightTrigger {
    pub word: String,
    pub line: usize,
    pub col: usize,
    pub is_symbol: bool,
}

impl BdsHighlightTrigger {
    pub fn new(word: &str, line: usize, col: usize) -> Self {
        Self { word: word.to_string(), line, col, is_symbol: false }
    }

    pub fn symbol(word: &str, line: usize, col: usize) -> Self {
        Self { word: word.to_string(), line, col, is_symbol: true }
    }

    pub fn is_empty(&self) -> bool {
        self.word.is_empty()
    }
}

/// Result of a document highlight request
#[derive(Debug, Clone, Default)]
pub struct BdsHighlightResult {
    pub highlights: Vec<BdsDocumentHighlight>,
    pub trigger: Option<BdsHighlightTrigger>,
}

impl BdsHighlightResult {
    pub fn new() -> Self { Self::default() }

    pub fn with_highlight(mut self, h: BdsDocumentHighlight) -> Self {
        self.highlights.push(h);
        self
    }

    pub fn with_trigger(mut self, t: BdsHighlightTrigger) -> Self {
        self.trigger = Some(t);
        self
    }

    pub fn count(&self) -> usize { self.highlights.len() }
    pub fn is_empty(&self) -> bool { self.highlights.is_empty() }

    pub fn read_count(&self) -> usize {
        self.highlights.iter().filter(|h| h.is_read()).count()
    }

    pub fn write_count(&self) -> usize {
        self.highlights.iter().filter(|h| h.is_write()).count()
    }

    pub fn highlights_on_line(&self, line: usize) -> Vec<&BdsDocumentHighlight> {
        self.highlights.iter().filter(|h| line >= h.start_line && line <= h.end_line).collect()
    }

    pub fn next_from(&self, line: usize, col: usize) -> Option<&BdsDocumentHighlight> {
        self.highlights.iter().find(|h| {
            h.start_line > line || (h.start_line == line && h.start_col > col)
        })
    }

    pub fn prev_from(&self, line: usize, col: usize) -> Option<&BdsDocumentHighlight> {
        self.highlights.iter().rev().find(|h| {
            h.start_line < line || (h.start_line == line && h.start_col < col)
        })
    }
}

/// Word highlight configuration
#[derive(Debug, Clone)]
pub struct BdsWordHighlightConfig {
    pub enabled: bool,
    pub delay_ms: u64,
    pub case_sensitive: bool,
    pub whole_word: bool,
    pub max_occurrences: usize,
}

impl Default for BdsWordHighlightConfig {
    fn default() -> Self {
        Self { enabled: true, delay_ms: 250, case_sensitive: true, whole_word: true, max_occurrences: 100 }
    }
}

#[cfg(test)]
mod tests_bds {
    use super::*;

    #[test]
    fn test_bds_highlight_read_write() {
        let r = BdsDocumentHighlight::read(1, 5, 1, 10);
        assert!(r.is_read());
        assert!(!r.is_write());
        let w = BdsDocumentHighlight::write(2, 0, 2, 5);
        assert!(w.is_write());
    }

    #[test]
    fn test_bds_highlight_contains() {
        let h = BdsDocumentHighlight::text(1, 5, 3, 10);
        assert!(h.contains_position(2, 0));
        assert!(!h.contains_position(0, 0));
        assert!(!h.contains_position(1, 3));
    }

    #[test]
    fn test_bds_trigger() {
        let t = BdsHighlightTrigger::new("hello", 1, 5);
        assert!(!t.is_empty());
        assert!(!t.is_symbol);
        let s = BdsHighlightTrigger::symbol("MyClass", 3, 10);
        assert!(s.is_symbol);
    }

    #[test]
    fn test_bds_result_counts() {
        let result = BdsHighlightResult::new()
            .with_highlight(BdsDocumentHighlight::read(1, 0, 1, 5))
            .with_highlight(BdsDocumentHighlight::write(3, 0, 3, 5))
            .with_highlight(BdsDocumentHighlight::read(5, 0, 5, 5));
        assert_eq!(result.count(), 3);
        assert_eq!(result.read_count(), 2);
        assert_eq!(result.write_count(), 1);
    }

    #[test]
    fn test_bds_result_line_query() {
        let result = BdsHighlightResult::new()
            .with_highlight(BdsDocumentHighlight::read(1, 0, 1, 5))
            .with_highlight(BdsDocumentHighlight::read(1, 10, 1, 15))
            .with_highlight(BdsDocumentHighlight::write(3, 0, 3, 5));
        assert_eq!(result.highlights_on_line(1).len(), 2);
        assert_eq!(result.highlights_on_line(3).len(), 1);
    }

    #[test]
    fn test_bds_result_navigation() {
        let result = BdsHighlightResult::new()
            .with_highlight(BdsDocumentHighlight::read(1, 0, 1, 5))
            .with_highlight(BdsDocumentHighlight::read(5, 0, 5, 5))
            .with_highlight(BdsDocumentHighlight::read(10, 0, 10, 5));
        let next = result.next_from(3, 0).unwrap();
        assert_eq!(next.start_line, 5);
        let prev = result.prev_from(7, 0).unwrap();
        assert_eq!(prev.start_line, 5);
    }

    #[test]
    fn test_bds_word_highlight_config() {
        let cfg = BdsWordHighlightConfig::default();
        assert!(cfg.enabled);
        assert_eq!(cfg.delay_ms, 250);
        assert!(cfg.case_sensitive);
        assert!(cfg.whole_word);
        assert_eq!(cfg.max_occurrences, 100);
    }

    #[test]
    fn test_bds_result_with_trigger() {
        let result = BdsHighlightResult::new()
            .with_trigger(BdsHighlightTrigger::new("hello", 1, 0))
            .with_highlight(BdsDocumentHighlight::text(1, 0, 1, 5));
        assert!(result.trigger.is_some());
        assert_eq!(result.trigger.unwrap().word, "hello");
    }

    #[test]
    fn test_bds_result_empty() {
        let result = BdsHighlightResult::new();
        assert!(result.is_empty());
        assert_eq!(result.count(), 0);
    }

    #[test]
    fn test_bds_highlight_access_variants() {
        let h = BdsDocumentHighlight::new(0, 0, 0, 5, BdsHighlightAccess::Text);
        assert!(!h.is_read());
        assert!(!h.is_write());
    }
}

// bdt_: Auto-close and auto-surround model — bracket pairs, quote pairs,
// surround selection, auto-closing before characters, language-specific

/// A character pair for auto-close behavior
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct BdtCharPair {
    pub open: char,
    pub close: char,
}

impl BdtCharPair {
    pub fn new(open: char, close: char) -> Self {
        Self { open, close }
    }

    pub fn is_symmetric(&self) -> bool {
        self.open == self.close
    }

    pub fn matches_open(&self, ch: char) -> bool {
        self.open == ch
    }

    pub fn matches_close(&self, ch: char) -> bool {
        self.close == ch
    }
}

/// Auto-close setting level
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BdtAutoCloseSetting {
    Always,
    LanguageDefined,
    BeforeWhitespace,
    Never,
}

impl BdtAutoCloseSetting {
    pub fn is_enabled(&self) -> bool {
        *self != BdtAutoCloseSetting::Never
    }
}

/// Auto-surround setting level
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BdtAutoSurroundSetting {
    LanguageDefined,
    Quotes,
    Brackets,
    Never,
}

impl BdtAutoSurroundSetting {
    pub fn allows_quotes(&self) -> bool {
        matches!(self, BdtAutoSurroundSetting::LanguageDefined | BdtAutoSurroundSetting::Quotes)
    }

    pub fn allows_brackets(&self) -> bool {
        matches!(self, BdtAutoSurroundSetting::LanguageDefined | BdtAutoSurroundSetting::Brackets)
    }
}

/// Configuration for auto-close behavior
#[derive(Debug, Clone)]
pub struct BdtAutoCloseConfig {
    pub bracket_pairs: Vec<BdtCharPair>,
    pub quote_pairs: Vec<BdtCharPair>,
    pub auto_close: BdtAutoCloseSetting,
    pub auto_surround: BdtAutoSurroundSetting,
    pub close_before_chars: Vec<char>,
}

impl Default for BdtAutoCloseConfig {
    fn default() -> Self {
        Self {
            bracket_pairs: vec![
                BdtCharPair::new('(', ')'),
                BdtCharPair::new('[', ']'),
                BdtCharPair::new('{', '}'),
            ],
            quote_pairs: vec![
                BdtCharPair::new('"', '"'),
                BdtCharPair::new('\'', '\''),
                BdtCharPair::new('`', '`'),
            ],
            auto_close: BdtAutoCloseSetting::LanguageDefined,
            auto_surround: BdtAutoSurroundSetting::LanguageDefined,
            close_before_chars: vec![' ', '\t', '}', ']', ')', '"', '\'', '`', ';', ',', '.'],
        }
    }
}

impl BdtAutoCloseConfig {
    pub fn find_bracket_pair(&self, ch: char) -> Option<&BdtCharPair> {
        self.bracket_pairs.iter().find(|p| p.matches_open(ch))
    }

    pub fn find_quote_pair(&self, ch: char) -> Option<&BdtCharPair> {
        self.quote_pairs.iter().find(|p| p.matches_open(ch))
    }

    pub fn find_close_pair(&self, ch: char) -> Option<&BdtCharPair> {
        self.bracket_pairs.iter().chain(self.quote_pairs.iter())
            .find(|p| p.matches_close(ch))
    }

    pub fn should_auto_close(&self, ch: char, next_char: Option<char>) -> bool {
        if !self.auto_close.is_enabled() { return false; }
        let is_pair = self.find_bracket_pair(ch).is_some() || self.find_quote_pair(ch).is_some();
        if !is_pair { return false; }
        match self.auto_close {
            BdtAutoCloseSetting::Always => true,
            BdtAutoCloseSetting::BeforeWhitespace => {
                next_char.is_none() || next_char.map_or(false, |c| c.is_whitespace())
            }
            BdtAutoCloseSetting::LanguageDefined => {
                next_char.is_none() || next_char.map_or(false, |c| self.close_before_chars.contains(&c))
            }
            BdtAutoCloseSetting::Never => false,
        }
    }

    pub fn should_auto_surround(&self, ch: char, has_selection: bool) -> bool {
        if !has_selection { return false; }
        match self.auto_surround {
            BdtAutoSurroundSetting::LanguageDefined => {
                self.find_bracket_pair(ch).is_some() || self.find_quote_pair(ch).is_some()
            }
            BdtAutoSurroundSetting::Brackets => self.find_bracket_pair(ch).is_some(),
            BdtAutoSurroundSetting::Quotes => self.find_quote_pair(ch).is_some(),
            BdtAutoSurroundSetting::Never => false,
        }
    }

    pub fn should_overtype(&self, ch: char) -> bool {
        self.bracket_pairs.iter().any(|p| p.matches_close(ch))
            || self.quote_pairs.iter().any(|p| p.matches_close(ch))
    }

    pub fn all_pairs(&self) -> Vec<&BdtCharPair> {
        self.bracket_pairs.iter().chain(self.quote_pairs.iter()).collect()
    }
}

#[cfg(test)]
mod tests_bdt {
    use super::*;

    #[test]
    fn test_bdt_char_pair() {
        let p = BdtCharPair::new('(', ')');
        assert!(!p.is_symmetric());
        assert!(p.matches_open('('));
        assert!(p.matches_close(')'));
        let q = BdtCharPair::new('"', '"');
        assert!(q.is_symmetric());
    }

    #[test]
    fn test_bdt_auto_close_setting() {
        assert!(BdtAutoCloseSetting::Always.is_enabled());
        assert!(BdtAutoCloseSetting::LanguageDefined.is_enabled());
        assert!(!BdtAutoCloseSetting::Never.is_enabled());
    }

    #[test]
    fn test_bdt_auto_surround_setting() {
        assert!(BdtAutoSurroundSetting::LanguageDefined.allows_quotes());
        assert!(BdtAutoSurroundSetting::LanguageDefined.allows_brackets());
        assert!(BdtAutoSurroundSetting::Quotes.allows_quotes());
        assert!(!BdtAutoSurroundSetting::Quotes.allows_brackets());
        assert!(!BdtAutoSurroundSetting::Brackets.allows_quotes());
        assert!(BdtAutoSurroundSetting::Brackets.allows_brackets());
    }

    #[test]
    fn test_bdt_config_find_pairs() {
        let cfg = BdtAutoCloseConfig::default();
        assert!(cfg.find_bracket_pair('(').is_some());
        assert!(cfg.find_bracket_pair('x').is_none());
        assert!(cfg.find_quote_pair('"').is_some());
        assert!(cfg.find_close_pair(')').is_some());
    }

    #[test]
    fn test_bdt_should_auto_close() {
        let cfg = BdtAutoCloseConfig::default();
        assert!(cfg.should_auto_close('(', Some(' ')));
        assert!(cfg.should_auto_close('{', Some('}')));
        assert!(cfg.should_auto_close('"', None));
        assert!(!cfg.should_auto_close('x', Some(' ')));
    }

    #[test]
    fn test_bdt_should_auto_close_never() {
        let mut cfg = BdtAutoCloseConfig::default();
        cfg.auto_close = BdtAutoCloseSetting::Never;
        assert!(!cfg.should_auto_close('(', Some(' ')));
    }

    #[test]
    fn test_bdt_should_auto_close_always() {
        let mut cfg = BdtAutoCloseConfig::default();
        cfg.auto_close = BdtAutoCloseSetting::Always;
        assert!(cfg.should_auto_close('(', Some('a')));
    }

    #[test]
    fn test_bdt_should_auto_surround() {
        let cfg = BdtAutoCloseConfig::default();
        assert!(cfg.should_auto_surround('(', true));
        assert!(!cfg.should_auto_surround('(', false));
        assert!(cfg.should_auto_surround('"', true));
    }

    #[test]
    fn test_bdt_should_overtype() {
        let cfg = BdtAutoCloseConfig::default();
        assert!(cfg.should_overtype(')'));
        assert!(cfg.should_overtype('"'));
        assert!(!cfg.should_overtype('a'));
    }

    #[test]
    fn test_bdt_all_pairs() {
        let cfg = BdtAutoCloseConfig::default();
        assert_eq!(cfg.all_pairs().len(), 6);
    }
}

// bdu_: Column/block selection model — rectangular selections,
// column editing, multi-line insert, block paste

/// A rectangular (column) selection
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BduColumnSelection {
    pub start_line: usize,
    pub start_col: usize,
    pub end_line: usize,
    pub end_col: usize,
}

impl BduColumnSelection {
    pub fn new(sl: usize, sc: usize, el: usize, ec: usize) -> Self {
        Self { start_line: sl, start_col: sc, end_line: el, end_col: ec }
    }

    pub fn top_line(&self) -> usize { self.start_line.min(self.end_line) }
    pub fn bottom_line(&self) -> usize { self.start_line.max(self.end_line) }
    pub fn left_col(&self) -> usize { self.start_col.min(self.end_col) }
    pub fn right_col(&self) -> usize { self.start_col.max(self.end_col) }

    pub fn line_count(&self) -> usize {
        self.bottom_line() - self.top_line() + 1
    }

    pub fn col_width(&self) -> usize {
        self.right_col() - self.left_col()
    }

    pub fn is_empty(&self) -> bool {
        self.col_width() == 0
    }

    pub fn is_reversed(&self) -> bool {
        self.end_line < self.start_line || (self.end_line == self.start_line && self.end_col < self.start_col)
    }

    pub fn contains_position(&self, line: usize, col: usize) -> bool {
        line >= self.top_line() && line <= self.bottom_line()
            && col >= self.left_col() && col < self.right_col()
    }

    pub fn line_ranges(&self) -> Vec<(usize, usize, usize)> {
        let left = self.left_col();
        let right = self.right_col();
        (self.top_line()..=self.bottom_line())
            .map(|line| (line, left, right))
            .collect()
    }

    pub fn expand_down(&mut self) {
        if self.end_line >= self.start_line {
            self.end_line += 1;
        } else {
            self.start_line += 1;
        }
    }

    pub fn expand_up(&mut self) {
        if self.end_line <= self.start_line {
            if self.end_line > 0 { self.end_line -= 1; }
        } else {
            if self.start_line > 0 { self.start_line -= 1; }
        }
    }

    pub fn expand_right(&mut self) {
        self.end_col += 1;
    }

    pub fn expand_left(&mut self) {
        if self.end_col > 0 { self.end_col -= 1; }
    }

    pub fn normalized(&self) -> Self {
        Self {
            start_line: self.top_line(),
            start_col: self.left_col(),
            end_line: self.bottom_line(),
            end_col: self.right_col(),
        }
    }
}

/// Block paste mode
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BduBlockPasteMode {
    /// Paste each line on a separate editor line
    Spread,
    /// Paste as column block at cursor
    Column,
    /// Paste as single text (normal)
    Normal,
}

/// Column selection state
#[derive(Debug, Clone, Default)]
pub struct BduColumnSelectionState {
    pub selection: Option<BduColumnSelection>,
    pub active: bool,
    pub clipboard: Vec<String>,
}

impl BduColumnSelectionState {
    pub fn new() -> Self { Self::default() }

    pub fn start(&mut self, line: usize, col: usize) {
        self.selection = Some(BduColumnSelection::new(line, col, line, col));
        self.active = true;
    }

    pub fn extend_to(&mut self, line: usize, col: usize) {
        if let Some(sel) = &mut self.selection {
            sel.end_line = line;
            sel.end_col = col;
        }
    }

    pub fn cancel(&mut self) {
        self.selection = None;
        self.active = false;
    }

    pub fn copy_lines(&mut self, lines: Vec<String>) {
        self.clipboard = lines;
    }

    pub fn has_clipboard(&self) -> bool {
        !self.clipboard.is_empty()
    }

    pub fn paste_mode(&self) -> BduBlockPasteMode {
        if self.clipboard.len() > 1 {
            BduBlockPasteMode::Column
        } else {
            BduBlockPasteMode::Normal
        }
    }

    pub fn is_active(&self) -> bool {
        self.active && self.selection.is_some()
    }
}

#[cfg(test)]
mod tests_bdu {
    use super::*;

    #[test]
    fn test_bdu_column_selection_basic() {
        let sel = BduColumnSelection::new(2, 5, 6, 10);
        assert_eq!(sel.top_line(), 2);
        assert_eq!(sel.bottom_line(), 6);
        assert_eq!(sel.left_col(), 5);
        assert_eq!(sel.right_col(), 10);
        assert_eq!(sel.line_count(), 5);
        assert_eq!(sel.col_width(), 5);
        assert!(!sel.is_empty());
        assert!(!sel.is_reversed());
    }

    #[test]
    fn test_bdu_column_selection_reversed() {
        let sel = BduColumnSelection::new(6, 10, 2, 5);
        assert!(sel.is_reversed());
        assert_eq!(sel.top_line(), 2);
        assert_eq!(sel.right_col(), 10);
    }

    #[test]
    fn test_bdu_column_selection_contains() {
        let sel = BduColumnSelection::new(2, 5, 6, 10);
        assert!(sel.contains_position(3, 7));
        assert!(!sel.contains_position(1, 7));
        assert!(!sel.contains_position(3, 3));
        assert!(!sel.contains_position(3, 10));
    }

    #[test]
    fn test_bdu_column_line_ranges() {
        let sel = BduColumnSelection::new(3, 5, 5, 15);
        let ranges = sel.line_ranges();
        assert_eq!(ranges.len(), 3);
        assert_eq!(ranges[0], (3, 5, 15));
        assert_eq!(ranges[2], (5, 5, 15));
    }

    #[test]
    fn test_bdu_column_expand() {
        let mut sel = BduColumnSelection::new(3, 5, 5, 10);
        sel.expand_down();
        assert_eq!(sel.end_line, 6);
        sel.expand_up();
        assert_eq!(sel.start_line, 2);
        sel.expand_right();
        assert_eq!(sel.end_col, 11);
        sel.expand_left();
        assert_eq!(sel.end_col, 10);
    }

    #[test]
    fn test_bdu_column_normalized() {
        let sel = BduColumnSelection::new(6, 10, 2, 5);
        let norm = sel.normalized();
        assert_eq!(norm.start_line, 2);
        assert_eq!(norm.start_col, 5);
        assert_eq!(norm.end_line, 6);
        assert_eq!(norm.end_col, 10);
    }

    #[test]
    fn test_bdu_state_start_extend() {
        let mut state = BduColumnSelectionState::new();
        state.start(3, 5);
        assert!(state.is_active());
        state.extend_to(7, 15);
        let sel = state.selection.as_ref().unwrap();
        assert_eq!(sel.end_line, 7);
        assert_eq!(sel.end_col, 15);
    }

    #[test]
    fn test_bdu_state_cancel() {
        let mut state = BduColumnSelectionState::new();
        state.start(0, 0);
        state.cancel();
        assert!(!state.is_active());
        assert!(state.selection.is_none());
    }

    #[test]
    fn test_bdu_state_clipboard() {
        let mut state = BduColumnSelectionState::new();
        assert!(!state.has_clipboard());
        state.copy_lines(vec!["abc".to_string(), "def".to_string()]);
        assert!(state.has_clipboard());
        assert_eq!(state.paste_mode(), BduBlockPasteMode::Column);
    }

    #[test]
    fn test_bdu_state_single_paste() {
        let mut state = BduColumnSelectionState::new();
        state.copy_lines(vec!["single".to_string()]);
        assert_eq!(state.paste_mode(), BduBlockPasteMode::Normal);
    }
}

// bdv_: Workspace folder model — multi-root workspace, folder add/remove,
// folder ordering, workspace file, trust per folder

/// Workspace folder entry
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BdvWorkspaceFolder {
    pub uri: String,
    pub name: String,
    pub index: usize,
    pub trusted: bool,
}

impl BdvWorkspaceFolder {
    pub fn new(uri: &str, name: &str, index: usize) -> Self {
        Self { uri: uri.to_string(), name: name.to_string(), index, trusted: true }
    }

    pub fn untrusted(mut self) -> Self {
        self.trusted = false;
        self
    }

    pub fn display_name(&self) -> &str {
        if self.name.is_empty() {
            self.uri.rsplit('/').next().unwrap_or(&self.uri)
        } else {
            &self.name
        }
    }

    pub fn is_file_scheme(&self) -> bool {
        self.uri.starts_with("file://")
    }

    pub fn path(&self) -> &str {
        self.uri.strip_prefix("file://").unwrap_or(&self.uri)
    }
}

/// Workspace configuration
#[derive(Debug, Clone)]
pub struct BdvWorkspaceConfig {
    pub folders: Vec<BdvWorkspaceFolder>,
    pub settings: std::collections::HashMap<String, String>,
    pub extensions_disabled: Vec<String>,
    pub workspace_file: Option<String>,
}

impl Default for BdvWorkspaceConfig {
    fn default() -> Self {
        Self {
            folders: Vec::new(),
            settings: std::collections::HashMap::new(),
            extensions_disabled: Vec::new(),
            workspace_file: None,
        }
    }
}

impl BdvWorkspaceConfig {
    pub fn new() -> Self { Self::default() }

    pub fn add_folder(&mut self, uri: &str, name: &str) {
        let idx = self.folders.len();
        self.folders.push(BdvWorkspaceFolder::new(uri, name, idx));
    }

    pub fn remove_folder(&mut self, uri: &str) -> bool {
        let before = self.folders.len();
        self.folders.retain(|f| f.uri != uri);
        if self.folders.len() < before {
            for (i, f) in self.folders.iter_mut().enumerate() {
                f.index = i;
            }
            true
        } else {
            false
        }
    }

    pub fn move_folder(&mut self, from: usize, to: usize) -> bool {
        if from >= self.folders.len() || to >= self.folders.len() { return false; }
        let folder = self.folders.remove(from);
        self.folders.insert(to, folder);
        for (i, f) in self.folders.iter_mut().enumerate() {
            f.index = i;
        }
        true
    }

    pub fn find_folder(&self, uri: &str) -> Option<&BdvWorkspaceFolder> {
        self.folders.iter().find(|f| f.uri == uri)
    }

    pub fn folder_count(&self) -> usize { self.folders.len() }

    pub fn is_multi_root(&self) -> bool { self.folders.len() > 1 }

    pub fn all_trusted(&self) -> bool {
        self.folders.iter().all(|f| f.trusted)
    }

    pub fn set_setting(&mut self, key: &str, value: &str) {
        self.settings.insert(key.to_string(), value.to_string());
    }

    pub fn get_setting(&self, key: &str) -> Option<&String> {
        self.settings.get(key)
    }

    pub fn folder_names(&self) -> Vec<&str> {
        self.folders.iter().map(|f| f.display_name()).collect()
    }
}

#[cfg(test)]
mod tests_bdv {
    use super::*;

    #[test]
    fn test_bdv_folder_basic() {
        let f = BdvWorkspaceFolder::new("file:///home/user/proj", "My Project", 0);
        assert_eq!(f.display_name(), "My Project");
        assert!(f.trusted);
        assert!(f.is_file_scheme());
        assert_eq!(f.path(), "/home/user/proj");
    }

    #[test]
    fn test_bdv_folder_untrusted() {
        let f = BdvWorkspaceFolder::new("file:///tmp/x", "", 0).untrusted();
        assert!(!f.trusted);
        assert_eq!(f.display_name(), "x");
    }

    #[test]
    fn test_bdv_config_add_remove() {
        let mut cfg = BdvWorkspaceConfig::new();
        cfg.add_folder("file:///a", "A");
        cfg.add_folder("file:///b", "B");
        assert_eq!(cfg.folder_count(), 2);
        assert!(cfg.is_multi_root());
        assert!(cfg.remove_folder("file:///a"));
        assert_eq!(cfg.folder_count(), 1);
        assert_eq!(cfg.folders[0].index, 0);
    }

    #[test]
    fn test_bdv_config_move() {
        let mut cfg = BdvWorkspaceConfig::new();
        cfg.add_folder("file:///a", "A");
        cfg.add_folder("file:///b", "B");
        cfg.add_folder("file:///c", "C");
        assert!(cfg.move_folder(2, 0));
        assert_eq!(cfg.folders[0].name, "C");
        assert_eq!(cfg.folders[0].index, 0);
        assert_eq!(cfg.folders[2].name, "B");
    }

    #[test]
    fn test_bdv_config_find() {
        let mut cfg = BdvWorkspaceConfig::new();
        cfg.add_folder("file:///proj", "Project");
        assert!(cfg.find_folder("file:///proj").is_some());
        assert!(cfg.find_folder("file:///other").is_none());
    }

    #[test]
    fn test_bdv_config_settings() {
        let mut cfg = BdvWorkspaceConfig::new();
        cfg.set_setting("editor.tabSize", "4");
        assert_eq!(cfg.get_setting("editor.tabSize").unwrap(), "4");
        assert!(cfg.get_setting("missing").is_none());
    }

    #[test]
    fn test_bdv_config_trust() {
        let mut cfg = BdvWorkspaceConfig::new();
        cfg.add_folder("file:///a", "A");
        assert!(cfg.all_trusted());
        cfg.folders[0].trusted = false;
        assert!(!cfg.all_trusted());
    }

    #[test]
    fn test_bdv_config_names() {
        let mut cfg = BdvWorkspaceConfig::new();
        cfg.add_folder("file:///a", "Alpha");
        cfg.add_folder("file:///b", "Beta");
        assert_eq!(cfg.folder_names(), vec!["Alpha", "Beta"]);
    }

    #[test]
    fn test_bdv_config_single_root() {
        let mut cfg = BdvWorkspaceConfig::new();
        cfg.add_folder("file:///proj", "P");
        assert!(!cfg.is_multi_root());
    }

    #[test]
    fn test_bdv_config_workspace_file() {
        let mut cfg = BdvWorkspaceConfig::new();
        cfg.workspace_file = Some("/home/user/my.code-workspace".to_string());
        assert!(cfg.workspace_file.is_some());
    }
}

// bdw_: Task runner and build model — task definitions, problem matchers,
// task groups, run/watch/test task types, task execution state

/// Task group kind
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BdwTaskGroup {
    Build,
    Test,
    Clean,
    Rebuild,
    None,
}

/// Task source origin
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BdwTaskSource {
    Workspace,
    Extension,
    User,
    Auto,
}

/// Task execution state
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BdwTaskState {
    Idle,
    Running,
    Succeeded,
    Failed,
    Cancelled,
}

impl BdwTaskState {
    pub fn is_terminal(&self) -> bool {
        matches!(self, BdwTaskState::Succeeded | BdwTaskState::Failed | BdwTaskState::Cancelled)
    }

    pub fn is_running(&self) -> bool {
        *self == BdwTaskState::Running
    }
}

/// Problem match severity
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BdwProblemSeverity {
    Error,
    Warning,
    Info,
}

/// A problem found by a problem matcher
#[derive(Debug, Clone)]
pub struct BdwProblem {
    pub file: String,
    pub line: usize,
    pub col: usize,
    pub message: String,
    pub severity: BdwProblemSeverity,
}

impl BdwProblem {
    pub fn error(file: &str, line: usize, col: usize, msg: &str) -> Self {
        Self { file: file.to_string(), line, col, message: msg.to_string(), severity: BdwProblemSeverity::Error }
    }

    pub fn warning(file: &str, line: usize, col: usize, msg: &str) -> Self {
        Self { file: file.to_string(), line, col, message: msg.to_string(), severity: BdwProblemSeverity::Warning }
    }

    pub fn is_error(&self) -> bool { self.severity == BdwProblemSeverity::Error }
}

/// A task definition
#[derive(Debug, Clone)]
pub struct BdwTask {
    pub label: String,
    pub command: String,
    pub args: Vec<String>,
    pub group: BdwTaskGroup,
    pub source: BdwTaskSource,
    pub state: BdwTaskState,
    pub problems: Vec<BdwProblem>,
    pub is_background: bool,
    pub exit_code: Option<i32>,
}

impl BdwTask {
    pub fn new(label: &str, command: &str) -> Self {
        Self {
            label: label.to_string(),
            command: command.to_string(),
            args: Vec::new(),
            group: BdwTaskGroup::None,
            source: BdwTaskSource::Workspace,
            state: BdwTaskState::Idle,
            problems: Vec::new(),
            is_background: false,
            exit_code: None,
        }
    }

    pub fn with_args(mut self, args: &[&str]) -> Self {
        self.args = args.iter().map(|s| s.to_string()).collect();
        self
    }

    pub fn with_group(mut self, group: BdwTaskGroup) -> Self {
        self.group = group;
        self
    }

    pub fn start(&mut self) {
        self.state = BdwTaskState::Running;
        self.problems.clear();
        self.exit_code = None;
    }

    pub fn complete(&mut self, exit_code: i32) {
        self.exit_code = Some(exit_code);
        self.state = if exit_code == 0 { BdwTaskState::Succeeded } else { BdwTaskState::Failed };
    }

    pub fn cancel(&mut self) {
        self.state = BdwTaskState::Cancelled;
    }

    pub fn add_problem(&mut self, problem: BdwProblem) {
        self.problems.push(problem);
    }

    pub fn error_count(&self) -> usize {
        self.problems.iter().filter(|p| p.is_error()).count()
    }

    pub fn command_line(&self) -> String {
        if self.args.is_empty() {
            self.command.clone()
        } else {
            format!("{} {}", self.command, self.args.join(" "))
        }
    }
}

/// Task registry
#[derive(Debug, Clone, Default)]
pub struct BdwTaskRegistry {
    pub tasks: Vec<BdwTask>,
}

impl BdwTaskRegistry {
    pub fn new() -> Self { Self::default() }

    pub fn add(&mut self, task: BdwTask) { self.tasks.push(task); }

    pub fn find(&self, label: &str) -> Option<&BdwTask> {
        self.tasks.iter().find(|t| t.label == label)
    }

    pub fn find_mut(&mut self, label: &str) -> Option<&mut BdwTask> {
        self.tasks.iter_mut().find(|t| t.label == label)
    }

    pub fn by_group(&self, group: BdwTaskGroup) -> Vec<&BdwTask> {
        self.tasks.iter().filter(|t| t.group == group).collect()
    }

    pub fn running_tasks(&self) -> Vec<&BdwTask> {
        self.tasks.iter().filter(|t| t.state.is_running()).collect()
    }

    pub fn count(&self) -> usize { self.tasks.len() }
}

#[cfg(test)]
mod tests_bdw {
    use super::*;

    #[test]
    fn test_bdw_task_state() {
        assert!(BdwTaskState::Succeeded.is_terminal());
        assert!(BdwTaskState::Failed.is_terminal());
        assert!(!BdwTaskState::Running.is_terminal());
        assert!(BdwTaskState::Running.is_running());
    }

    #[test]
    fn test_bdw_problem() {
        let p = BdwProblem::error("src/main.rs", 10, 5, "undefined variable");
        assert!(p.is_error());
        let w = BdwProblem::warning("src/lib.rs", 20, 1, "unused import");
        assert!(!w.is_error());
    }

    #[test]
    fn test_bdw_task_lifecycle() {
        let mut task = BdwTask::new("build", "cargo").with_args(&["build"]).with_group(BdwTaskGroup::Build);
        assert_eq!(task.state, BdwTaskState::Idle);
        task.start();
        assert!(task.state.is_running());
        task.add_problem(BdwProblem::error("a.rs", 1, 1, "err"));
        task.complete(1);
        assert_eq!(task.state, BdwTaskState::Failed);
        assert_eq!(task.error_count(), 1);
        assert_eq!(task.exit_code, Some(1));
    }

    #[test]
    fn test_bdw_task_success() {
        let mut task = BdwTask::new("test", "cargo").with_args(&["test"]);
        task.start();
        task.complete(0);
        assert_eq!(task.state, BdwTaskState::Succeeded);
    }

    #[test]
    fn test_bdw_task_cancel() {
        let mut task = BdwTask::new("watch", "npm").with_args(&["run", "watch"]);
        task.is_background = true;
        task.start();
        task.cancel();
        assert_eq!(task.state, BdwTaskState::Cancelled);
    }

    #[test]
    fn test_bdw_task_command_line() {
        let task = BdwTask::new("build", "cargo").with_args(&["build", "--release"]);
        assert_eq!(task.command_line(), "cargo build --release");
    }

    #[test]
    fn test_bdw_task_command_line_no_args() {
        let task = BdwTask::new("make", "make");
        assert_eq!(task.command_line(), "make");
    }

    #[test]
    fn test_bdw_registry() {
        let mut reg = BdwTaskRegistry::new();
        reg.add(BdwTask::new("build", "cargo").with_group(BdwTaskGroup::Build));
        reg.add(BdwTask::new("test", "cargo").with_group(BdwTaskGroup::Test));
        assert_eq!(reg.count(), 2);
        assert!(reg.find("build").is_some());
        assert_eq!(reg.by_group(BdwTaskGroup::Build).len(), 1);
    }

    #[test]
    fn test_bdw_registry_running() {
        let mut reg = BdwTaskRegistry::new();
        reg.add(BdwTask::new("build", "cargo"));
        reg.find_mut("build").unwrap().start();
        assert_eq!(reg.running_tasks().len(), 1);
    }

    #[test]
    fn test_bdw_task_source() {
        let task = BdwTask::new("lint", "eslint");
        assert_eq!(task.source, BdwTaskSource::Workspace);
    }
}

// bdx_: Terminal profile model — shell profiles, default shell,
// terminal appearance, environment, icon, terminal tab title

/// Terminal profile shell type
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BdxShellType {
    Bash,
    Zsh,
    Fish,
    PowerShell,
    Cmd,
    GitBash,
    Tmux,
    Custom,
}

impl BdxShellType {
    pub fn default_path(&self) -> &str {
        match self {
            BdxShellType::Bash => "/bin/bash",
            BdxShellType::Zsh => "/bin/zsh",
            BdxShellType::Fish => "/usr/bin/fish",
            BdxShellType::PowerShell => "pwsh",
            BdxShellType::Cmd => "cmd.exe",
            BdxShellType::GitBash => "C:\\Program Files\\Git\\bin\\bash.exe",
            BdxShellType::Tmux => "/usr/bin/tmux",
            BdxShellType::Custom => "",
        }
    }

    pub fn display_name(&self) -> &str {
        match self {
            BdxShellType::Bash => "bash",
            BdxShellType::Zsh => "zsh",
            BdxShellType::Fish => "fish",
            BdxShellType::PowerShell => "PowerShell",
            BdxShellType::Cmd => "Command Prompt",
            BdxShellType::GitBash => "Git Bash",
            BdxShellType::Tmux => "tmux",
            BdxShellType::Custom => "Custom",
        }
    }
}

/// Terminal profile
#[derive(Debug, Clone)]
pub struct BdxTerminalProfile {
    pub name: String,
    pub shell_type: BdxShellType,
    pub path: String,
    pub args: Vec<String>,
    pub env: std::collections::HashMap<String, String>,
    pub icon: Option<String>,
    pub color: Option<String>,
    pub is_default: bool,
    pub cwd: Option<String>,
}

impl BdxTerminalProfile {
    pub fn new(name: &str, shell: BdxShellType) -> Self {
        Self {
            name: name.to_string(),
            shell_type: shell,
            path: shell.default_path().to_string(),
            args: Vec::new(),
            env: std::collections::HashMap::new(),
            icon: None,
            color: None,
            is_default: false,
            cwd: None,
        }
    }

    pub fn with_path(mut self, path: &str) -> Self {
        self.path = path.to_string();
        self
    }

    pub fn with_arg(mut self, arg: &str) -> Self {
        self.args.push(arg.to_string());
        self
    }

    pub fn with_env(mut self, key: &str, val: &str) -> Self {
        self.env.insert(key.to_string(), val.to_string());
        self
    }

    pub fn with_icon(mut self, icon: &str) -> Self {
        self.icon = Some(icon.to_string());
        self
    }

    pub fn set_default(&mut self) { self.is_default = true; }

    pub fn command_line(&self) -> String {
        if self.args.is_empty() {
            self.path.clone()
        } else {
            format!("{} {}", self.path, self.args.join(" "))
        }
    }
}

/// Terminal profile registry
#[derive(Debug, Clone, Default)]
pub struct BdxProfileRegistry {
    pub profiles: Vec<BdxTerminalProfile>,
}

impl BdxProfileRegistry {
    pub fn new() -> Self { Self::default() }

    pub fn add(&mut self, profile: BdxTerminalProfile) {
        self.profiles.push(profile);
    }

    pub fn default_profile(&self) -> Option<&BdxTerminalProfile> {
        self.profiles.iter().find(|p| p.is_default).or(self.profiles.first())
    }

    pub fn find(&self, name: &str) -> Option<&BdxTerminalProfile> {
        self.profiles.iter().find(|p| p.name == name)
    }

    pub fn names(&self) -> Vec<&str> {
        self.profiles.iter().map(|p| p.name.as_str()).collect()
    }

    pub fn count(&self) -> usize { self.profiles.len() }

    pub fn remove(&mut self, name: &str) -> bool {
        let before = self.profiles.len();
        self.profiles.retain(|p| p.name != name);
        self.profiles.len() < before
    }
}

#[cfg(test)]
mod tests_bdx {
    use super::*;

    #[test]
    fn test_bdx_shell_type() {
        assert_eq!(BdxShellType::Bash.default_path(), "/bin/bash");
        assert_eq!(BdxShellType::Zsh.display_name(), "zsh");
        assert_eq!(BdxShellType::PowerShell.display_name(), "PowerShell");
    }

    #[test]
    fn test_bdx_profile_basic() {
        let p = BdxTerminalProfile::new("My Bash", BdxShellType::Bash);
        assert_eq!(p.name, "My Bash");
        assert_eq!(p.path, "/bin/bash");
        assert!(!p.is_default);
    }

    #[test]
    fn test_bdx_profile_custom() {
        let p = BdxTerminalProfile::new("Custom", BdxShellType::Custom)
            .with_path("/usr/local/bin/mysh")
            .with_arg("--login")
            .with_env("TERM", "xterm-256color")
            .with_icon("terminal");
        assert_eq!(p.command_line(), "/usr/local/bin/mysh --login");
        assert_eq!(p.env.get("TERM").unwrap(), "xterm-256color");
        assert_eq!(p.icon.as_deref(), Some("terminal"));
    }

    #[test]
    fn test_bdx_profile_default() {
        let mut p = BdxTerminalProfile::new("zsh", BdxShellType::Zsh);
        p.set_default();
        assert!(p.is_default);
    }

    #[test]
    fn test_bdx_registry_add_find() {
        let mut reg = BdxProfileRegistry::new();
        reg.add(BdxTerminalProfile::new("bash", BdxShellType::Bash));
        reg.add(BdxTerminalProfile::new("zsh", BdxShellType::Zsh));
        assert_eq!(reg.count(), 2);
        assert!(reg.find("bash").is_some());
        assert!(reg.find("fish").is_none());
    }

    #[test]
    fn test_bdx_registry_default() {
        let mut reg = BdxProfileRegistry::new();
        reg.add(BdxTerminalProfile::new("bash", BdxShellType::Bash));
        let mut zsh = BdxTerminalProfile::new("zsh", BdxShellType::Zsh);
        zsh.set_default();
        reg.add(zsh);
        assert_eq!(reg.default_profile().unwrap().name, "zsh");
    }

    #[test]
    fn test_bdx_registry_default_fallback() {
        let mut reg = BdxProfileRegistry::new();
        reg.add(BdxTerminalProfile::new("bash", BdxShellType::Bash));
        assert_eq!(reg.default_profile().unwrap().name, "bash");
    }

    #[test]
    fn test_bdx_registry_names() {
        let mut reg = BdxProfileRegistry::new();
        reg.add(BdxTerminalProfile::new("a", BdxShellType::Bash));
        reg.add(BdxTerminalProfile::new("b", BdxShellType::Zsh));
        assert_eq!(reg.names(), vec!["a", "b"]);
    }

    #[test]
    fn test_bdx_registry_remove() {
        let mut reg = BdxProfileRegistry::new();
        reg.add(BdxTerminalProfile::new("bash", BdxShellType::Bash));
        assert!(reg.remove("bash"));
        assert_eq!(reg.count(), 0);
        assert!(!reg.remove("bash"));
    }

    #[test]
    fn test_bdx_profile_no_args_command() {
        let p = BdxTerminalProfile::new("bash", BdxShellType::Bash);
        assert_eq!(p.command_line(), "/bin/bash");
    }
}

// bdy_: Editor decoration model — inline decorations, gutter decorations,
// overview ruler, decoration ranges, decoration types, render options

/// Decoration position in editor
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BdyDecorationPosition {
    InlineText,
    InlineAfter,
    InlineBefore,
    Gutter,
    OverviewRuler,
    Minimap,
    Margin,
}

/// Overview ruler lane
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BdyRulerLane {
    Left,
    Center,
    Right,
    Full,
}

/// A decoration type definition
#[derive(Debug, Clone)]
pub struct BdyDecorationType {
    pub id: String,
    pub background_color: Option<String>,
    pub border_color: Option<String>,
    pub foreground_color: Option<String>,
    pub font_weight: Option<String>,
    pub font_style: Option<String>,
    pub text_decoration: Option<String>,
    pub gutter_icon: Option<String>,
    pub ruler_color: Option<String>,
    pub ruler_lane: BdyRulerLane,
    pub is_whole_line: bool,
}

impl BdyDecorationType {
    pub fn new(id: &str) -> Self {
        Self {
            id: id.to_string(),
            background_color: None,
            border_color: None,
            foreground_color: None,
            font_weight: None,
            font_style: None,
            text_decoration: None,
            gutter_icon: None,
            ruler_color: None,
            ruler_lane: BdyRulerLane::Center,
            is_whole_line: false,
        }
    }

    pub fn with_background(mut self, color: &str) -> Self {
        self.background_color = Some(color.to_string()); self
    }

    pub fn with_border(mut self, color: &str) -> Self {
        self.border_color = Some(color.to_string()); self
    }

    pub fn with_foreground(mut self, color: &str) -> Self {
        self.foreground_color = Some(color.to_string()); self
    }

    pub fn with_gutter_icon(mut self, icon: &str) -> Self {
        self.gutter_icon = Some(icon.to_string()); self
    }

    pub fn with_ruler(mut self, color: &str, lane: BdyRulerLane) -> Self {
        self.ruler_color = Some(color.to_string());
        self.ruler_lane = lane;
        self
    }

    pub fn whole_line(mut self) -> Self {
        self.is_whole_line = true; self
    }

    pub fn has_ruler(&self) -> bool { self.ruler_color.is_some() }
    pub fn has_gutter(&self) -> bool { self.gutter_icon.is_some() }
}

/// A decoration range (instance of a type applied to text)
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BdyDecorationRange {
    pub type_id: String,
    pub start_line: usize,
    pub start_col: usize,
    pub end_line: usize,
    pub end_col: usize,
    pub hover_message: Option<String>,
}

impl BdyDecorationRange {
    pub fn new(type_id: &str, sl: usize, sc: usize, el: usize, ec: usize) -> Self {
        Self {
            type_id: type_id.to_string(),
            start_line: sl, start_col: sc,
            end_line: el, end_col: ec,
            hover_message: None,
        }
    }

    pub fn with_hover(mut self, msg: &str) -> Self {
        self.hover_message = Some(msg.to_string()); self
    }

    pub fn on_line(&self, line: usize) -> bool {
        line >= self.start_line && line <= self.end_line
    }

    pub fn is_single_line(&self) -> bool {
        self.start_line == self.end_line
    }
}

/// Decoration set for an editor
#[derive(Debug, Clone, Default)]
pub struct BdyDecorationSet {
    pub types: Vec<BdyDecorationType>,
    pub ranges: Vec<BdyDecorationRange>,
}

impl BdyDecorationSet {
    pub fn new() -> Self { Self::default() }

    pub fn register_type(&mut self, dt: BdyDecorationType) {
        self.types.push(dt);
    }

    pub fn set_ranges(&mut self, type_id: &str, ranges: Vec<BdyDecorationRange>) {
        self.ranges.retain(|r| r.type_id != type_id);
        self.ranges.extend(ranges);
    }

    pub fn ranges_for_line(&self, line: usize) -> Vec<&BdyDecorationRange> {
        self.ranges.iter().filter(|r| r.on_line(line)).collect()
    }

    pub fn dispose_type(&mut self, type_id: &str) {
        self.types.retain(|t| t.id != type_id);
        self.ranges.retain(|r| r.type_id != type_id);
    }

    pub fn type_count(&self) -> usize { self.types.len() }
    pub fn range_count(&self) -> usize { self.ranges.len() }
}

#[cfg(test)]
mod tests_bdy {
    use super::*;

    #[test]
    fn test_bdy_decoration_type() {
        let dt = BdyDecorationType::new("error")
            .with_background("#ff0000")
            .with_border("#cc0000")
            .with_foreground("#ffffff")
            .with_gutter_icon("error-icon")
            .with_ruler("#ff0000", BdyRulerLane::Right)
            .whole_line();
        assert!(dt.has_ruler());
        assert!(dt.has_gutter());
        assert!(dt.is_whole_line);
    }

    #[test]
    fn test_bdy_decoration_type_minimal() {
        let dt = BdyDecorationType::new("highlight");
        assert!(!dt.has_ruler());
        assert!(!dt.has_gutter());
        assert!(!dt.is_whole_line);
    }

    #[test]
    fn test_bdy_decoration_range() {
        let r = BdyDecorationRange::new("error", 5, 0, 5, 20).with_hover("Error here");
        assert!(r.on_line(5));
        assert!(!r.on_line(6));
        assert!(r.is_single_line());
        assert_eq!(r.hover_message.as_deref(), Some("Error here"));
    }

    #[test]
    fn test_bdy_decoration_range_multiline() {
        let r = BdyDecorationRange::new("warning", 3, 0, 7, 10);
        assert!(r.on_line(5));
        assert!(!r.is_single_line());
    }

    #[test]
    fn test_bdy_decoration_set_register() {
        let mut set = BdyDecorationSet::new();
        set.register_type(BdyDecorationType::new("error").with_background("#f00"));
        set.register_type(BdyDecorationType::new("warn").with_background("#ff0"));
        assert_eq!(set.type_count(), 2);
    }

    #[test]
    fn test_bdy_decoration_set_ranges() {
        let mut set = BdyDecorationSet::new();
        set.set_ranges("error", vec![
            BdyDecorationRange::new("error", 1, 0, 1, 10),
            BdyDecorationRange::new("error", 5, 0, 5, 15),
        ]);
        assert_eq!(set.range_count(), 2);
        assert_eq!(set.ranges_for_line(1).len(), 1);
        assert_eq!(set.ranges_for_line(5).len(), 1);
        assert_eq!(set.ranges_for_line(3).len(), 0);
    }

    #[test]
    fn test_bdy_decoration_set_replace_ranges() {
        let mut set = BdyDecorationSet::new();
        set.set_ranges("err", vec![BdyDecorationRange::new("err", 1, 0, 1, 5)]);
        assert_eq!(set.range_count(), 1);
        set.set_ranges("err", vec![BdyDecorationRange::new("err", 2, 0, 2, 5)]);
        assert_eq!(set.range_count(), 1);
        assert_eq!(set.ranges_for_line(2).len(), 1);
    }

    #[test]
    fn test_bdy_decoration_set_dispose() {
        let mut set = BdyDecorationSet::new();
        set.register_type(BdyDecorationType::new("error"));
        set.set_ranges("error", vec![BdyDecorationRange::new("error", 1, 0, 1, 5)]);
        set.dispose_type("error");
        assert_eq!(set.type_count(), 0);
        assert_eq!(set.range_count(), 0);
    }

    #[test]
    fn test_bdy_ruler_lanes() {
        assert_eq!(BdyRulerLane::Left, BdyRulerLane::Left);
        assert_ne!(BdyRulerLane::Left, BdyRulerLane::Right);
    }

    #[test]
    fn test_bdy_decoration_positions() {
        assert_ne!(BdyDecorationPosition::InlineText, BdyDecorationPosition::Gutter);
        assert_eq!(BdyDecorationPosition::OverviewRuler, BdyDecorationPosition::OverviewRuler);
    }
}

// bdz_: Command registry model — command IDs, command handler, keybinding
// resolution, when-clause context, command palette entries

/// Command execution result
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum BdzCommandResult {
    Success,
    NotFound,
    Disabled,
    Error(String),
}

impl BdzCommandResult {
    pub fn is_success(&self) -> bool { *self == BdzCommandResult::Success }
    pub fn is_error(&self) -> bool { matches!(self, BdzCommandResult::Error(_)) }
}

/// A when-clause condition for command enablement
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum BdzWhenClause {
    True,
    False,
    Key(String),
    Not(Box<BdzWhenClause>),
    And(Vec<BdzWhenClause>),
    Or(Vec<BdzWhenClause>),
    Equals(String, String),
}

impl BdzWhenClause {
    pub fn key(k: &str) -> Self { BdzWhenClause::Key(k.to_string()) }
    pub fn not(clause: BdzWhenClause) -> Self { BdzWhenClause::Not(Box::new(clause)) }
    pub fn equals(k: &str, v: &str) -> Self { BdzWhenClause::Equals(k.to_string(), v.to_string()) }

    pub fn evaluate(&self, ctx: &std::collections::HashMap<String, String>) -> bool {
        match self {
            BdzWhenClause::True => true,
            BdzWhenClause::False => false,
            BdzWhenClause::Key(k) => ctx.get(k).map_or(false, |v| v != "false" && !v.is_empty()),
            BdzWhenClause::Not(inner) => !inner.evaluate(ctx),
            BdzWhenClause::And(clauses) => clauses.iter().all(|c| c.evaluate(ctx)),
            BdzWhenClause::Or(clauses) => clauses.iter().any(|c| c.evaluate(ctx)),
            BdzWhenClause::Equals(k, v) => ctx.get(k).map_or(false, |cv| cv == v),
        }
    }
}

/// A registered command
#[derive(Debug, Clone)]
pub struct BdzCommand {
    pub id: String,
    pub title: String,
    pub category: Option<String>,
    pub icon: Option<String>,
    pub when: Option<BdzWhenClause>,
    pub keybinding: Option<String>,
}

impl BdzCommand {
    pub fn new(id: &str, title: &str) -> Self {
        Self {
            id: id.to_string(),
            title: title.to_string(),
            category: None,
            icon: None,
            when: None,
            keybinding: None,
        }
    }

    pub fn with_category(mut self, cat: &str) -> Self {
        self.category = Some(cat.to_string()); self
    }

    pub fn with_icon(mut self, icon: &str) -> Self {
        self.icon = Some(icon.to_string()); self
    }

    pub fn with_when(mut self, when: BdzWhenClause) -> Self {
        self.when = Some(when); self
    }

    pub fn with_keybinding(mut self, kb: &str) -> Self {
        self.keybinding = Some(kb.to_string()); self
    }

    pub fn display_label(&self) -> String {
        if let Some(cat) = &self.category {
            format!("{}: {}", cat, self.title)
        } else {
            self.title.clone()
        }
    }

    pub fn is_enabled(&self, ctx: &std::collections::HashMap<String, String>) -> bool {
        self.when.as_ref().map_or(true, |w| w.evaluate(ctx))
    }
}

/// Command registry
#[derive(Debug, Clone, Default)]
pub struct BdzCommandRegistry {
    pub commands: Vec<BdzCommand>,
}

impl BdzCommandRegistry {
    pub fn new() -> Self { Self::default() }

    pub fn register(&mut self, cmd: BdzCommand) {
        self.commands.push(cmd);
    }

    pub fn find(&self, id: &str) -> Option<&BdzCommand> {
        self.commands.iter().find(|c| c.id == id)
    }

    pub fn execute(&self, id: &str, ctx: &std::collections::HashMap<String, String>) -> BdzCommandResult {
        match self.find(id) {
            None => BdzCommandResult::NotFound,
            Some(cmd) => {
                if !cmd.is_enabled(ctx) {
                    BdzCommandResult::Disabled
                } else {
                    BdzCommandResult::Success
                }
            }
        }
    }

    pub fn palette_entries(&self, ctx: &std::collections::HashMap<String, String>) -> Vec<&BdzCommand> {
        self.commands.iter().filter(|c| c.is_enabled(ctx)).collect()
    }

    pub fn search(&self, query: &str) -> Vec<&BdzCommand> {
        let q = query.to_lowercase();
        self.commands.iter().filter(|c| {
            c.title.to_lowercase().contains(&q)
                || c.id.to_lowercase().contains(&q)
                || c.category.as_ref().map_or(false, |cat| cat.to_lowercase().contains(&q))
        }).collect()
    }

    pub fn by_keybinding(&self, kb: &str) -> Vec<&BdzCommand> {
        self.commands.iter().filter(|c| c.keybinding.as_deref() == Some(kb)).collect()
    }

    pub fn count(&self) -> usize { self.commands.len() }
}

#[cfg(test)]
mod tests_bdz {
    use super::*;

    #[test]
    fn test_bdz_command_result() {
        assert!(BdzCommandResult::Success.is_success());
        assert!(!BdzCommandResult::NotFound.is_success());
        assert!(BdzCommandResult::Error("oops".into()).is_error());
    }

    #[test]
    fn test_bdz_when_clause_key() {
        let mut ctx = std::collections::HashMap::new();
        ctx.insert("editorFocus".to_string(), "true".to_string());
        assert!(BdzWhenClause::key("editorFocus").evaluate(&ctx));
        assert!(!BdzWhenClause::key("terminalFocus").evaluate(&ctx));
    }

    #[test]
    fn test_bdz_when_clause_not() {
        let ctx = std::collections::HashMap::new();
        assert!(BdzWhenClause::not(BdzWhenClause::key("missing")).evaluate(&ctx));
    }

    #[test]
    fn test_bdz_when_clause_and_or() {
        let mut ctx = std::collections::HashMap::new();
        ctx.insert("a".to_string(), "true".to_string());
        let and = BdzWhenClause::And(vec![BdzWhenClause::key("a"), BdzWhenClause::key("b")]);
        assert!(!and.evaluate(&ctx));
        let or = BdzWhenClause::Or(vec![BdzWhenClause::key("a"), BdzWhenClause::key("b")]);
        assert!(or.evaluate(&ctx));
    }

    #[test]
    fn test_bdz_when_clause_equals() {
        let mut ctx = std::collections::HashMap::new();
        ctx.insert("lang".to_string(), "rust".to_string());
        assert!(BdzWhenClause::equals("lang", "rust").evaluate(&ctx));
        assert!(!BdzWhenClause::equals("lang", "python").evaluate(&ctx));
    }

    #[test]
    fn test_bdz_command_display() {
        let cmd = BdzCommand::new("editor.action.format", "Format Document")
            .with_category("Editor");
        assert_eq!(cmd.display_label(), "Editor: Format Document");
        let cmd2 = BdzCommand::new("workbench.action.quit", "Quit");
        assert_eq!(cmd2.display_label(), "Quit");
    }

    #[test]
    fn test_bdz_command_enabled() {
        let mut ctx = std::collections::HashMap::new();
        ctx.insert("editorFocus".to_string(), "true".to_string());
        let cmd = BdzCommand::new("test", "Test")
            .with_when(BdzWhenClause::key("editorFocus"));
        assert!(cmd.is_enabled(&ctx));
    }

    #[test]
    fn test_bdz_registry_register_find() {
        let mut reg = BdzCommandRegistry::new();
        reg.register(BdzCommand::new("editor.format", "Format").with_keybinding("Ctrl+Shift+F"));
        reg.register(BdzCommand::new("editor.save", "Save").with_keybinding("Ctrl+S"));
        assert_eq!(reg.count(), 2);
        assert!(reg.find("editor.format").is_some());
        assert!(reg.find("missing").is_none());
    }

    #[test]
    fn test_bdz_registry_execute() {
        let mut reg = BdzCommandRegistry::new();
        reg.register(BdzCommand::new("cmd1", "Cmd1"));
        let ctx = std::collections::HashMap::new();
        assert!(reg.execute("cmd1", &ctx).is_success());
        assert_eq!(reg.execute("missing", &ctx), BdzCommandResult::NotFound);
    }

    #[test]
    fn test_bdz_registry_search() {
        let mut reg = BdzCommandRegistry::new();
        reg.register(BdzCommand::new("editor.format", "Format Document").with_category("Editor"));
        reg.register(BdzCommand::new("editor.save", "Save File"));
        let results = reg.search("format");
        assert_eq!(results.len(), 1);
        assert_eq!(results[0].id, "editor.format");
    }

    #[test]
    fn test_bdz_registry_keybinding() {
        let mut reg = BdzCommandRegistry::new();
        reg.register(BdzCommand::new("save", "Save").with_keybinding("Ctrl+S"));
        reg.register(BdzCommand::new("copy", "Copy").with_keybinding("Ctrl+C"));
        let bound = reg.by_keybinding("Ctrl+S");
        assert_eq!(bound.len(), 1);
        assert_eq!(bound[0].id, "save");
    }
}

// bea_: Editor scroll model — scroll position, smooth scrolling,
// scroll acceleration, viewport tracking, scroll-past-end

/// Scroll direction
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BeaScrollDirection {
    Up,
    Down,
    Left,
    Right,
}

/// Scroll animation type
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BeaScrollAnimation {
    None,
    Smooth,
    Instant,
}

/// Editor scroll state
#[derive(Debug, Clone)]
pub struct BeaScrollState {
    pub top_line: usize,
    pub left_col: usize,
    pub viewport_lines: usize,
    pub viewport_cols: usize,
    pub total_lines: usize,
    pub total_cols: usize,
    pub smooth_scrolling: bool,
    pub scroll_past_end: bool,
    pub scroll_speed: f64,
}

impl Default for BeaScrollState {
    fn default() -> Self {
        Self {
            top_line: 0, left_col: 0,
            viewport_lines: 40, viewport_cols: 120,
            total_lines: 0, total_cols: 0,
            smooth_scrolling: true,
            scroll_past_end: false,
            scroll_speed: 3.0,
        }
    }
}

impl BeaScrollState {
    pub fn new(viewport_lines: usize, viewport_cols: usize) -> Self {
        Self { viewport_lines, viewport_cols, ..Default::default() }
    }

    pub fn max_top_line(&self) -> usize {
        if self.scroll_past_end {
            self.total_lines.saturating_sub(1)
        } else {
            self.total_lines.saturating_sub(self.viewport_lines)
        }
    }

    pub fn visible_range(&self) -> (usize, usize) {
        (self.top_line, (self.top_line + self.viewport_lines).min(self.total_lines))
    }

    pub fn is_line_visible(&self, line: usize) -> bool {
        line >= self.top_line && line < self.top_line + self.viewport_lines
    }

    pub fn scroll_to_line(&mut self, line: usize) {
        self.top_line = line.min(self.max_top_line());
    }

    pub fn scroll_by(&mut self, lines: isize) {
        let new_top = if lines >= 0 {
            self.top_line.saturating_add(lines as usize)
        } else {
            self.top_line.saturating_sub((-lines) as usize)
        };
        self.top_line = new_top.min(self.max_top_line());
    }

    pub fn scroll_to_reveal(&mut self, line: usize, margin: usize) {
        if line < self.top_line + margin {
            self.top_line = line.saturating_sub(margin);
        } else if line >= self.top_line + self.viewport_lines - margin {
            self.scroll_to_line(line.saturating_sub(self.viewport_lines - margin - 1));
        }
    }

    pub fn page_up(&mut self) {
        self.scroll_by(-(self.viewport_lines as isize));
    }

    pub fn page_down(&mut self) {
        self.scroll_by(self.viewport_lines as isize);
    }

    pub fn scroll_to_top(&mut self) {
        self.top_line = 0;
    }

    pub fn scroll_to_bottom(&mut self) {
        self.top_line = self.max_top_line();
    }

    pub fn scroll_fraction(&self) -> f64 {
        if self.total_lines == 0 { return 0.0; }
        self.top_line as f64 / self.total_lines as f64
    }

    pub fn is_at_top(&self) -> bool { self.top_line == 0 }

    pub fn is_at_bottom(&self) -> bool {
        self.top_line >= self.max_top_line()
    }
}

#[cfg(test)]
mod tests_bea {
    use super::*;

    #[test]
    fn test_bea_scroll_defaults() {
        let s = BeaScrollState::default();
        assert!(s.smooth_scrolling);
        assert!(!s.scroll_past_end);
        assert_eq!(s.scroll_speed, 3.0);
    }

    #[test]
    fn test_bea_visible_range() {
        let mut s = BeaScrollState::new(10, 80);
        s.total_lines = 100;
        assert_eq!(s.visible_range(), (0, 10));
        s.top_line = 50;
        assert_eq!(s.visible_range(), (50, 60));
    }

    #[test]
    fn test_bea_is_line_visible() {
        let mut s = BeaScrollState::new(10, 80);
        s.total_lines = 100;
        s.top_line = 20;
        assert!(s.is_line_visible(25));
        assert!(!s.is_line_visible(10));
        assert!(!s.is_line_visible(30));
    }

    #[test]
    fn test_bea_scroll_by() {
        let mut s = BeaScrollState::new(10, 80);
        s.total_lines = 100;
        s.scroll_by(5);
        assert_eq!(s.top_line, 5);
        s.scroll_by(-3);
        assert_eq!(s.top_line, 2);
        s.scroll_by(-10);
        assert_eq!(s.top_line, 0);
    }

    #[test]
    fn test_bea_scroll_to_line() {
        let mut s = BeaScrollState::new(10, 80);
        s.total_lines = 50;
        s.scroll_to_line(45);
        assert_eq!(s.top_line, 40); // max is 50-10=40
    }

    #[test]
    fn test_bea_page_up_down() {
        let mut s = BeaScrollState::new(10, 80);
        s.total_lines = 100;
        s.page_down();
        assert_eq!(s.top_line, 10);
        s.page_up();
        assert_eq!(s.top_line, 0);
    }

    #[test]
    fn test_bea_scroll_to_top_bottom() {
        let mut s = BeaScrollState::new(10, 80);
        s.total_lines = 100;
        s.scroll_to_bottom();
        assert_eq!(s.top_line, 90);
        assert!(s.is_at_bottom());
        s.scroll_to_top();
        assert!(s.is_at_top());
    }

    #[test]
    fn test_bea_scroll_reveal() {
        let mut s = BeaScrollState::new(10, 80);
        s.total_lines = 100;
        s.top_line = 20;
        s.scroll_to_reveal(15, 2);
        assert_eq!(s.top_line, 13);
    }

    #[test]
    fn test_bea_scroll_fraction() {
        let mut s = BeaScrollState::new(10, 80);
        s.total_lines = 100;
        s.top_line = 50;
        assert!((s.scroll_fraction() - 0.5).abs() < 0.001);
    }

    #[test]
    fn test_bea_scroll_past_end() {
        let mut s = BeaScrollState::new(10, 80);
        s.total_lines = 100;
        s.scroll_past_end = true;
        s.scroll_to_line(99);
        assert_eq!(s.top_line, 99);
    }
}

// beb_: Editor cursor blink model — blink phases, blink rate, cursor style,
// visibility toggling, animation timer, cursor width

/// Cursor style
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BebCursorStyle {
    Line,
    Block,
    Underline,
    LineThin,
    BlockOutline,
    UnderlineThin,
}

impl BebCursorStyle {
    pub fn is_block(&self) -> bool {
        matches!(self, BebCursorStyle::Block | BebCursorStyle::BlockOutline)
    }

    pub fn is_line(&self) -> bool {
        matches!(self, BebCursorStyle::Line | BebCursorStyle::LineThin)
    }

    pub fn width(&self) -> u32 {
        match self {
            BebCursorStyle::Line => 2,
            BebCursorStyle::LineThin => 1,
            BebCursorStyle::Block | BebCursorStyle::BlockOutline => 0,
            BebCursorStyle::Underline => 0,
            BebCursorStyle::UnderlineThin => 0,
        }
    }
}

/// Cursor blink phase
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BebBlinkPhase {
    On,
    Off,
}

/// Cursor blink animation type
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BebBlinkAnimation {
    Blink,
    Smooth,
    Phase,
    Expand,
    Solid,
}

impl BebBlinkAnimation {
    pub fn is_animated(&self) -> bool {
        *self != BebBlinkAnimation::Solid
    }
}

/// Cursor blink state
#[derive(Debug, Clone)]
pub struct BebCursorBlink {
    pub style: BebCursorStyle,
    pub animation: BebBlinkAnimation,
    pub blink_rate_ms: u64,
    pub phase: BebBlinkPhase,
    pub visible: bool,
    pub elapsed_ms: u64,
    pub paused: bool,
}

impl Default for BebCursorBlink {
    fn default() -> Self {
        Self {
            style: BebCursorStyle::Line,
            animation: BebBlinkAnimation::Blink,
            blink_rate_ms: 530,
            phase: BebBlinkPhase::On,
            visible: true,
            elapsed_ms: 0,
            paused: false,
        }
    }
}

impl BebCursorBlink {
    pub fn new() -> Self { Self::default() }

    pub fn tick(&mut self, delta_ms: u64) {
        if self.paused || !self.animation.is_animated() { return; }
        self.elapsed_ms += delta_ms;
        if self.elapsed_ms >= self.blink_rate_ms {
            self.elapsed_ms -= self.blink_rate_ms;
            self.phase = match self.phase {
                BebBlinkPhase::On => BebBlinkPhase::Off,
                BebBlinkPhase::Off => BebBlinkPhase::On,
            };
            self.visible = self.phase == BebBlinkPhase::On;
        }
    }

    pub fn reset(&mut self) {
        self.elapsed_ms = 0;
        self.phase = BebBlinkPhase::On;
        self.visible = true;
    }

    pub fn pause(&mut self) {
        self.paused = true;
        self.visible = true;
    }

    pub fn resume(&mut self) {
        self.paused = false;
        self.reset();
    }

    pub fn set_style(&mut self, style: BebCursorStyle) {
        self.style = style;
    }

    pub fn set_blink_rate(&mut self, ms: u64) {
        self.blink_rate_ms = ms;
        self.reset();
    }

    pub fn is_visible(&self) -> bool {
        self.paused || !self.animation.is_animated() || self.visible
    }

    pub fn opacity(&self) -> f64 {
        if self.is_visible() { 1.0 } else { 0.0 }
    }
}

#[cfg(test)]
mod tests_beb {
    use super::*;

    #[test]
    fn test_beb_cursor_style() {
        assert!(BebCursorStyle::Block.is_block());
        assert!(BebCursorStyle::Line.is_line());
        assert!(!BebCursorStyle::Underline.is_block());
        assert_eq!(BebCursorStyle::Line.width(), 2);
        assert_eq!(BebCursorStyle::LineThin.width(), 1);
    }

    #[test]
    fn test_beb_blink_animation() {
        assert!(BebBlinkAnimation::Blink.is_animated());
        assert!(!BebBlinkAnimation::Solid.is_animated());
    }

    #[test]
    fn test_beb_blink_defaults() {
        let b = BebCursorBlink::new();
        assert_eq!(b.blink_rate_ms, 530);
        assert!(b.is_visible());
        assert_eq!(b.opacity(), 1.0);
    }

    #[test]
    fn test_beb_blink_tick() {
        let mut b = BebCursorBlink::new();
        b.tick(200);
        assert!(b.is_visible());
        b.tick(400); // 600ms > 530ms → toggles off
        assert!(!b.visible);
        assert!(!b.is_visible());
    }

    #[test]
    fn test_beb_blink_reset() {
        let mut b = BebCursorBlink::new();
        b.tick(600);
        assert!(!b.visible);
        b.reset();
        assert!(b.visible);
        assert_eq!(b.elapsed_ms, 0);
    }

    #[test]
    fn test_beb_blink_pause_resume() {
        let mut b = BebCursorBlink::new();
        b.tick(600);
        b.pause();
        assert!(b.is_visible()); // paused always visible
        b.tick(600); // no-op while paused
        assert!(b.is_visible());
        b.resume();
        assert!(b.is_visible()); // just resumed, reset
    }

    #[test]
    fn test_beb_blink_solid() {
        let mut b = BebCursorBlink::new();
        b.animation = BebBlinkAnimation::Solid;
        b.tick(1000);
        assert!(b.is_visible()); // solid never blinks
    }

    #[test]
    fn test_beb_set_style() {
        let mut b = BebCursorBlink::new();
        b.set_style(BebCursorStyle::Block);
        assert_eq!(b.style, BebCursorStyle::Block);
    }

    #[test]
    fn test_beb_set_blink_rate() {
        let mut b = BebCursorBlink::new();
        b.set_blink_rate(1000);
        assert_eq!(b.blink_rate_ms, 1000);
        assert_eq!(b.elapsed_ms, 0);
    }

    #[test]
    fn test_beb_opacity() {
        let mut b = BebCursorBlink::new();
        assert_eq!(b.opacity(), 1.0);
        b.tick(600);
        assert_eq!(b.opacity(), 0.0);
    }
}

// bec_: Editor indentation model — indent size, tab/spaces, auto-indent,
// indent guides, re-indent, trim trailing whitespace

/// Indent mode
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BecIndentMode {
    Tabs,
    Spaces,
}

/// Auto-indent behavior
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BecAutoIndent {
    None,
    Keep,
    Brackets,
    Advanced,
    Full,
}

impl BecAutoIndent {
    pub fn should_increase_after_open_bracket(&self) -> bool {
        matches!(self, BecAutoIndent::Brackets | BecAutoIndent::Advanced | BecAutoIndent::Full)
    }

    pub fn should_decrease_before_close_bracket(&self) -> bool {
        matches!(self, BecAutoIndent::Brackets | BecAutoIndent::Advanced | BecAutoIndent::Full)
    }
}

/// Indentation configuration
#[derive(Debug, Clone)]
pub struct BecIndentConfig {
    pub mode: BecIndentMode,
    pub size: usize,
    pub auto_indent: BecAutoIndent,
    pub detect_indentation: bool,
    pub trim_trailing_whitespace: bool,
    pub insert_final_newline: bool,
    pub render_guides: bool,
    pub guide_active_color: String,
    pub guide_inactive_color: String,
}

impl Default for BecIndentConfig {
    fn default() -> Self {
        Self {
            mode: BecIndentMode::Spaces,
            size: 4,
            auto_indent: BecAutoIndent::Advanced,
            detect_indentation: true,
            trim_trailing_whitespace: false,
            insert_final_newline: false,
            render_guides: true,
            guide_active_color: "#707070".to_string(),
            guide_inactive_color: "#404040".to_string(),
        }
    }
}

impl BecIndentConfig {
    pub fn indent_string(&self) -> String {
        match self.mode {
            BecIndentMode::Tabs => "\t".to_string(),
            BecIndentMode::Spaces => " ".repeat(self.size),
        }
    }

    pub fn indent_at_level(&self, level: usize) -> String {
        self.indent_string().repeat(level)
    }

    pub fn measure_indent(&self, line: &str) -> usize {
        let spaces: usize = line.chars().take_while(|c| c.is_whitespace()).map(|c| {
            if c == '\t' { self.size } else { 1 }
        }).sum();
        spaces / self.size
    }

    pub fn normalize_indent(&self, line: &str) -> String {
        let level = self.measure_indent(line);
        let content = line.trim_start();
        format!("{}{}", self.indent_at_level(level), content)
    }

    pub fn trim_trailing(&self, line: &str) -> String {
        if self.trim_trailing_whitespace {
            line.trim_end().to_string()
        } else {
            line.to_string()
        }
    }
}

/// Detect indentation from text content
pub fn bec_detect_indentation(lines: &[&str]) -> (BecIndentMode, usize) {
    let mut tab_count = 0;
    let mut space_counts = [0usize; 9]; // indices 1..8
    for line in lines {
        if line.is_empty() { continue; }
        if line.starts_with('\t') {
            tab_count += 1;
        } else {
            let spaces = line.chars().take_while(|c| *c == ' ').count();
            if spaces > 0 && spaces <= 8 {
                space_counts[spaces] += 1;
            }
        }
    }
    if tab_count > space_counts.iter().sum::<usize>() / 2 {
        return (BecIndentMode::Tabs, 4);
    }
    let best_size = (2..=8).max_by_key(|&s| space_counts[s]).unwrap_or(4);
    (BecIndentMode::Spaces, best_size)
}

