// bfz_ Type Hierarchy Model

/// Kind of type in a hierarchy.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BfzTypeKind {
    Class,
    Interface,
    Struct,
    Enum,
    TypeAlias,
    Trait,
}

/// Direction of type hierarchy traversal.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BfzHierarchyDirection {
    Supertypes,
    Subtypes,
}

/// A type in the hierarchy tree.
#[derive(Debug, Clone)]
pub struct BfzTypeItem {
    pub name: String,
    pub kind: BfzTypeKind,
    pub uri: String,
    pub line: usize,
    pub detail: Option<String>,
    pub children: Vec<BfzTypeItem>,
    pub is_expanded: bool,
}

/// Type hierarchy model for displaying super/sub-type relationships.
#[derive(Debug, Clone)]
pub struct BfzTypeHierarchy {
    pub root: Option<BfzTypeItem>,
    pub direction: BfzHierarchyDirection,
    pub is_visible: bool,
}

impl BfzTypeHierarchy {
    pub fn new() -> Self {
        Self { root: None, direction: BfzHierarchyDirection::Supertypes, is_visible: false }
    }

    pub fn set_root(&mut self, item: BfzTypeItem) {
        self.root = Some(item);
        self.is_visible = true;
    }

    pub fn set_direction(&mut self, dir: BfzHierarchyDirection) {
        self.direction = dir;
    }

    pub fn clear(&mut self) {
        self.root = None;
        self.is_visible = false;
    }

    pub fn depth(&self) -> usize {
        fn measure(item: &BfzTypeItem) -> usize {
            if item.children.is_empty() {
                1
            } else {
                1 + item.children.iter().map(|c| measure(c)).max().unwrap_or(0)
            }
        }
        self.root.as_ref().map(|r| measure(r)).unwrap_or(0)
    }

    pub fn total_items(&self) -> usize {
        fn count(item: &BfzTypeItem) -> usize {
            1 + item.children.iter().map(|c| count(c)).sum::<usize>()
        }
        self.root.as_ref().map(|r| count(r)).unwrap_or(0)
    }

    pub fn toggle_expand(&mut self, path: &[usize]) {
        if let Some(root) = &mut self.root {
            let mut current = root;
            for &idx in path {
                if idx < current.children.len() {
                    current = &mut current.children[idx];
                } else {
                    return;
                }
            }
            current.is_expanded = !current.is_expanded;
        }
    }

    pub fn is_visible(&self) -> bool {
        self.is_visible
    }

    pub fn root_name(&self) -> Option<&str> {
        self.root.as_ref().map(|r| r.name.as_str())
    }
}



// bga_ Editor Scroll State Model

/// Scroll direction.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BgaScrollDirection {
    Up,
    Down,
    Left,
    Right,
}

/// Smooth scroll animation state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BgaScrollAnimation {
    None,
    Smooth,
    Instant,
}

/// Editor scroll state.
#[derive(Debug, Clone)]
pub struct BgaScrollState {
    pub scroll_top: f64,
    pub scroll_left: f64,
    pub viewport_height: f64,
    pub viewport_width: f64,
    pub content_height: f64,
    pub content_width: f64,
    pub animation: BgaScrollAnimation,
}

impl BgaScrollState {
    pub fn new(viewport_h: f64, viewport_w: f64) -> Self {
        Self {
            scroll_top: 0.0, scroll_left: 0.0,
            viewport_height: viewport_h, viewport_width: viewport_w,
            content_height: 0.0, content_width: 0.0,
            animation: BgaScrollAnimation::Smooth,
        }
    }

    pub fn scroll_by(&mut self, dx: f64, dy: f64) {
        self.scroll_top = (self.scroll_top + dy).max(0.0).min(self.max_scroll_top());
        self.scroll_left = (self.scroll_left + dx).max(0.0).min(self.max_scroll_left());
    }

    pub fn scroll_to(&mut self, top: f64, left: f64) {
        self.scroll_top = top.max(0.0).min(self.max_scroll_top());
        self.scroll_left = left.max(0.0).min(self.max_scroll_left());
    }

    pub fn scroll_to_top(&mut self) {
        self.scroll_top = 0.0;
    }

    pub fn scroll_to_bottom(&mut self) {
        self.scroll_top = self.max_scroll_top();
    }

    pub fn max_scroll_top(&self) -> f64 {
        (self.content_height - self.viewport_height).max(0.0)
    }

    pub fn max_scroll_left(&self) -> f64 {
        (self.content_width - self.viewport_width).max(0.0)
    }

    pub fn is_at_top(&self) -> bool {
        self.scroll_top <= 0.0
    }

    pub fn is_at_bottom(&self) -> bool {
        self.scroll_top >= self.max_scroll_top()
    }

    pub fn visible_range_lines(&self, line_height: f64) -> (usize, usize) {
        if line_height <= 0.0 { return (0, 0); }
        let first = (self.scroll_top / line_height) as usize;
        let visible = (self.viewport_height / line_height).ceil() as usize;
        (first, first + visible)
    }

    pub fn set_content_size(&mut self, height: f64, width: f64) {
        self.content_height = height;
        self.content_width = width;
    }

    pub fn scroll_fraction(&self) -> f64 {
        let max = self.max_scroll_top();
        if max <= 0.0 { 0.0 } else { self.scroll_top / max }
    }
}


// bgb_ Editor Cursor Blink Model

/// Cursor blink style.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BgbBlinkStyle {
    Blink,
    Smooth,
    Phase,
    Expand,
    Solid,
    Hidden,
}

/// Cursor shape.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BgbCursorShape {
    Line,
    Block,
    Underline,
    LineThin,
    BlockOutline,
    UnderlineThin,
}

/// Cursor blink and rendering model.
#[derive(Debug, Clone)]
pub struct BgbCursorModel {
    pub shape: BgbCursorShape,
    pub blink_style: BgbBlinkStyle,
    pub blink_interval_ms: u32,
    pub is_visible: bool,
    pub is_focused: bool,
    tick_count: u64,
}

impl BgbCursorModel {
    pub fn new() -> Self {
        Self {
            shape: BgbCursorShape::Line,
            blink_style: BgbBlinkStyle::Blink,
            blink_interval_ms: 530,
            is_visible: true,
            is_focused: true,
            tick_count: 0,
        }
    }

    pub fn tick(&mut self) {
        self.tick_count += 1;
        match self.blink_style {
            BgbBlinkStyle::Solid => self.is_visible = true,
            BgbBlinkStyle::Hidden => self.is_visible = false,
            BgbBlinkStyle::Blink => self.is_visible = self.tick_count % 2 == 0,
            BgbBlinkStyle::Smooth | BgbBlinkStyle::Phase | BgbBlinkStyle::Expand => {
                self.is_visible = true; // animation handled by renderer
            }
        }
    }

    pub fn reset_blink(&mut self) {
        self.tick_count = 0;
        self.is_visible = true;
    }

    pub fn set_shape(&mut self, shape: BgbCursorShape) {
        self.shape = shape;
    }

    pub fn set_blink_style(&mut self, style: BgbBlinkStyle) {
        self.blink_style = style;
        self.reset_blink();
    }

    pub fn set_focused(&mut self, focused: bool) {
        self.is_focused = focused;
        if focused { self.reset_blink(); }
    }

    pub fn should_render(&self) -> bool {
        self.is_focused && self.is_visible
    }

    pub fn opacity(&self) -> f64 {
        if !self.is_focused { return 0.4; }
        if self.is_visible { 1.0 } else { 0.0 }
    }
}


