pub struct BgsRuler {
    pub column: usize,
    pub color: Option<String>,
}

/// Rulers model for vertical column guidelines.
#[derive(Debug, Clone)]
pub struct BgsRulersModel {
    rulers: Vec<BgsRuler>,
    is_visible: bool,
}

impl BgsRulersModel {
    pub fn new() -> Self { Self { rulers: Vec::new(), is_visible: true } }

    pub fn set_rulers(&mut self, columns: Vec<usize>) {
        self.rulers = columns.into_iter().map(|c| BgsRuler { column: c, color: None }).collect();
    }

    pub fn add_ruler(&mut self, column: usize, color: Option<&str>) {
        self.rulers.push(BgsRuler { column, color: color.map(String::from) });
    }

    pub fn remove_ruler(&mut self, column: usize) {
        self.rulers.retain(|r| r.column != column);
    }

    pub fn has_ruler_at(&self, column: usize) -> bool {
        self.rulers.iter().any(|r| r.column == column)
    }

    pub fn columns(&self) -> Vec<usize> {
        let mut cols: Vec<usize> = self.rulers.iter().map(|r| r.column).collect();
        cols.sort(); cols
    }

    pub fn toggle_visibility(&mut self) { self.is_visible = !self.is_visible; }
    pub fn is_visible(&self) -> bool { self.is_visible }
    pub fn count(&self) -> usize { self.rulers.len() }
    pub fn clear(&mut self) { self.rulers.clear(); }

    pub fn rightmost(&self) -> Option<usize> {
        self.rulers.iter().map(|r| r.column).max()
    }
}


// bgt_ Editor Whitespace Rendering Model

/// Whitespace rendering mode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BgtWhitespaceMode {
    None,
    Boundary,
    Selection,
    Trailing,
    All,
}

/// Whitespace character representation.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BgtWhitespaceChar {
    Space,
    Tab,
    NonBreakingSpace,
    FullWidthSpace,
}

/// Whitespace rendering model.
#[derive(Debug, Clone)]
pub struct BgtWhitespaceModel {
    pub mode: BgtWhitespaceMode,
    pub tab_size: usize,
    pub use_spaces: bool,
    pub trim_trailing_on_save: bool,
    pub insert_final_newline: bool,
    pub trim_final_newlines: bool,
}

impl BgtWhitespaceModel {
    pub fn new() -> Self {
        Self {
            mode: BgtWhitespaceMode::Selection,
            tab_size: 4, use_spaces: true,
            trim_trailing_on_save: false,
            insert_final_newline: false,
            trim_final_newlines: false,
        }
    }

    pub fn set_mode(&mut self, mode: BgtWhitespaceMode) { self.mode = mode; }
    pub fn set_tab_size(&mut self, size: usize) { self.tab_size = size.max(1).min(16); }
    pub fn toggle_use_spaces(&mut self) { self.use_spaces = !self.use_spaces; }

    pub fn should_render_at(&self, is_boundary: bool, is_selected: bool, is_trailing: bool) -> bool {
        match self.mode {
            BgtWhitespaceMode::None => false,
            BgtWhitespaceMode::All => true,
            BgtWhitespaceMode::Boundary => is_boundary,
            BgtWhitespaceMode::Selection => is_selected,
            BgtWhitespaceMode::Trailing => is_trailing,
        }
    }

    pub fn indent_string(&self) -> String {
        if self.use_spaces {
            " ".repeat(self.tab_size)
        } else {
            "\t".to_string()
        }
    }

    pub fn detect_indentation(&self, lines: &[&str]) -> (bool, usize) {
        let mut space_counts = [0u32; 9];
        let mut tab_count = 0u32;
        for line in lines.iter().take(100) {
            if line.starts_with('\t') { tab_count += 1; }
            else {
                let spaces = line.len() - line.trim_start_matches(' ').len();
                if spaces > 0 && spaces <= 8 { space_counts[spaces] += 1; }
            }
        }
        let max_space = space_counts.iter().enumerate().skip(1).max_by_key(|&(_, &c)| c).map(|(i, _)| i).unwrap_or(4);
        let total_spaces: u32 = space_counts.iter().sum();
        (total_spaces >= tab_count, max_space)
    }
}



// bgu_ Editor Line Numbers Model

/// Line numbers display mode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BguLineNumberMode {
    On,
    Off,
    Relative,
    Interval,
}

/// Line numbers model.
#[derive(Debug, Clone)]
pub struct BguLineNumbersModel {
    pub mode: BguLineNumberMode,
    pub interval: usize,
    pub current_line: usize,
    pub total_lines: usize,
}

impl BguLineNumbersModel {
    pub fn new(total: usize) -> Self {
        Self { mode: BguLineNumberMode::On, interval: 10, current_line: 1, total_lines: total }
    }

    pub fn set_mode(&mut self, mode: BguLineNumberMode) { self.mode = mode; }
    pub fn set_current_line(&mut self, line: usize) { self.current_line = line; }
    pub fn set_total_lines(&mut self, total: usize) { self.total_lines = total; }

    pub fn display_number(&self, line: usize) -> Option<String> {
        match self.mode {
            BguLineNumberMode::Off => None,
            BguLineNumberMode::On => Some(line.to_string()),
            BguLineNumberMode::Relative => {
                if line == self.current_line { Some(line.to_string()) }
                else { Some(((line as isize) - (self.current_line as isize)).unsigned_abs().to_string()) }
            }
            BguLineNumberMode::Interval => {
                if line == self.current_line || line % self.interval == 0 || line == 1 {
                    Some(line.to_string())
                } else { None }
            }
        }
    }

    pub fn gutter_width(&self) -> usize {
        let digits = format!("{}", self.total_lines).len();
        digits.max(2) + 1
    }

    pub fn is_visible(&self) -> bool { self.mode != BguLineNumberMode::Off }
}


// bgv_ Editor Cursor Style Model

/// Multi-cursor behavior when typing.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BgvMultiCursorModifier {
    CtrlCmd,
    Alt,
}

/// Cursor surrounding pairs insertion mode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BgvAutoSurround {
    LanguageDefined,
    Quotes,
    Brackets,
    Never,
}

/// Cursor behavior model.
#[derive(Debug, Clone)]
pub struct BgvCursorBehavior {
    pub multi_cursor_modifier: BgvMultiCursorModifier,
    pub auto_surround: BgvAutoSurround,
    pub cursor_smooth_caret: bool,
    pub cursor_width: u32,
    pub sticky_tab_stops: bool,
    pub cursor_surrounding_lines: usize,
    pub cursor_surrounding_lines_style: BgvSurroundingStyle,
}

/// How surrounding lines are calculated.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BgvSurroundingStyle {
    Default,
    All,
}

impl BgvCursorBehavior {
    pub fn new() -> Self {
        Self {
            multi_cursor_modifier: BgvMultiCursorModifier::Alt,
            auto_surround: BgvAutoSurround::LanguageDefined,
            cursor_smooth_caret: true,
            cursor_width: 2,
            sticky_tab_stops: false,
            cursor_surrounding_lines: 0,
            cursor_surrounding_lines_style: BgvSurroundingStyle::Default,
        }
    }

    pub fn visible_range(&self, current_line: usize, total_lines: usize) -> (usize, usize) {
        let margin = self.cursor_surrounding_lines;
        let start = current_line.saturating_sub(margin);
        let end = (current_line + margin).min(total_lines);
        (start, end)
    }

    pub fn set_width(&mut self, w: u32) { self.cursor_width = w.max(1).min(10); }
    pub fn toggle_smooth_caret(&mut self) { self.cursor_smooth_caret = !self.cursor_smooth_caret; }
    pub fn toggle_sticky_tabs(&mut self) { self.sticky_tab_stops = !self.sticky_tab_stops; }
}


