// bgx_ Editor Auto Save Model

/// Auto save mode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BgxAutoSaveMode {
    Off,
    AfterDelay,
    OnFocusChange,
    OnWindowChange,
}

/// Auto save configuration model.
#[derive(Debug, Clone)]
pub struct BgxAutoSaveModel {
    pub mode: BgxAutoSaveMode,
    pub delay_ms: u64,
    pub pending_save: bool,
    pub last_save_tick: u64,
    pub dirty_since_tick: Option<u64>,
}

impl BgxAutoSaveModel {
    pub fn new() -> Self {
        Self {
            mode: BgxAutoSaveMode::Off, delay_ms: 1000,
            pending_save: false, last_save_tick: 0, dirty_since_tick: None,
        }
    }

    pub fn set_mode(&mut self, mode: BgxAutoSaveMode) { self.mode = mode; }
    pub fn set_delay(&mut self, ms: u64) { self.delay_ms = ms.max(100); }

    pub fn mark_dirty(&mut self, tick: u64) {
        if self.dirty_since_tick.is_none() { self.dirty_since_tick = Some(tick); }
    }

    pub fn mark_saved(&mut self, tick: u64) {
        self.dirty_since_tick = None;
        self.pending_save = false;
        self.last_save_tick = tick;
    }

    pub fn should_save(&self, current_tick: u64) -> bool {
        match self.mode {
            BgxAutoSaveMode::Off => false,
            BgxAutoSaveMode::AfterDelay => {
                if let Some(dirty_tick) = self.dirty_since_tick {
                    current_tick - dirty_tick >= self.delay_ms
                } else { false }
            }
            BgxAutoSaveMode::OnFocusChange | BgxAutoSaveMode::OnWindowChange => {
                self.dirty_since_tick.is_some()
            }
        }
    }

    pub fn on_focus_change(&mut self) -> bool {
        if self.mode == BgxAutoSaveMode::OnFocusChange && self.dirty_since_tick.is_some() {
            self.pending_save = true; true
        } else { false }
    }

    pub fn on_window_change(&mut self) -> bool {
        if self.mode == BgxAutoSaveMode::OnWindowChange && self.dirty_since_tick.is_some() {
            self.pending_save = true; true
        } else { false }
    }

    pub fn is_dirty(&self) -> bool { self.dirty_since_tick.is_some() }
    pub fn is_enabled(&self) -> bool { self.mode != BgxAutoSaveMode::Off }
}


// bgy_ Editor Format On Type Model

/// Format trigger kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BgyFormatTrigger {
    OnType,
    OnPaste,
    OnSave,
    Manual,
}

/// Format on type model.
#[derive(Debug, Clone)]
pub struct BgyFormatOnTypeModel {
    pub enabled_on_type: bool,
    pub enabled_on_paste: bool,
    pub enabled_on_save: bool,
    pub trigger_chars: Vec<char>,
    pub default_formatter: Option<String>,
}

impl BgyFormatOnTypeModel {
    pub fn new() -> Self {
        Self {
            enabled_on_type: false, enabled_on_paste: false, enabled_on_save: false,
            trigger_chars: vec!['}', ';', '\n'],
            default_formatter: None,
        }
    }

    pub fn should_format(&self, trigger: BgyFormatTrigger) -> bool {
        match trigger {
            BgyFormatTrigger::OnType => self.enabled_on_type,
            BgyFormatTrigger::OnPaste => self.enabled_on_paste,
            BgyFormatTrigger::OnSave => self.enabled_on_save,
            BgyFormatTrigger::Manual => true,
        }
    }

    pub fn is_trigger_char(&self, ch: char) -> bool { self.trigger_chars.contains(&ch) }
    pub fn add_trigger_char(&mut self, ch: char) { if !self.trigger_chars.contains(&ch) { self.trigger_chars.push(ch); } }
    pub fn remove_trigger_char(&mut self, ch: char) { self.trigger_chars.retain(|&c| c != ch); }

    pub fn set_formatter(&mut self, id: &str) { self.default_formatter = Some(id.to_string()); }
    pub fn clear_formatter(&mut self) { self.default_formatter = None; }

    pub fn toggle_on_type(&mut self) { self.enabled_on_type = !self.enabled_on_type; }
    pub fn toggle_on_paste(&mut self) { self.enabled_on_paste = !self.enabled_on_paste; }
    pub fn toggle_on_save(&mut self) { self.enabled_on_save = !self.enabled_on_save; }
}


// bgz_ Editor Accessibility Model

/// Screen reader accessibility mode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BgzAccessibilityMode {
    Auto,
    On,
    Off,
}

/// Accessibility support level.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BgzAccessibilitySupport {
    Unknown,
    Enabled,
    Disabled,
}

/// Editor accessibility model.
#[derive(Debug, Clone)]
pub struct BgzAccessibilityModel {
    pub mode: BgzAccessibilityMode,
    pub support: BgzAccessibilitySupport,
    pub page_size: usize,
    pub announce_messages: bool,
    pub tab_focus_mode: bool,
    pub high_contrast: bool,
}

impl BgzAccessibilityModel {
    pub fn new() -> Self {
        Self {
            mode: BgzAccessibilityMode::Auto,
            support: BgzAccessibilitySupport::Unknown,
            page_size: 10,
            announce_messages: true,
            tab_focus_mode: false,
            high_contrast: false,
        }
    }

    pub fn is_screen_reader_active(&self) -> bool {
        match self.mode {
            BgzAccessibilityMode::On => true,
            BgzAccessibilityMode::Off => false,
            BgzAccessibilityMode::Auto => self.support == BgzAccessibilitySupport::Enabled,
        }
    }

    pub fn set_mode(&mut self, mode: BgzAccessibilityMode) { self.mode = mode; }
    pub fn set_support(&mut self, support: BgzAccessibilitySupport) { self.support = support; }
    pub fn toggle_tab_focus(&mut self) { self.tab_focus_mode = !self.tab_focus_mode; }
    pub fn toggle_high_contrast(&mut self) { self.high_contrast = !self.high_contrast; }

    pub fn effective_page_size(&self) -> usize {
        if self.is_screen_reader_active() { self.page_size } else { 0 }
    }

    pub fn should_announce(&self) -> bool {
        self.announce_messages && self.is_screen_reader_active()
    }
}



// bha_ Editor Outline View Model

/// Symbol kind in the outline view.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BhaOutlineSymbolKind {
    File, Module, Namespace, Package, Class, Method, Property, Field,
    Constructor, Enum, Interface, Function, Variable, Constant, String,
    Number, Boolean, Array, Object, Key, Null, EnumMember, Struct, Event,
    Operator, TypeParameter,
}

/// An outline symbol node.
#[derive(Debug, Clone)]
pub struct BhaOutlineNode {
    pub name: String,
    pub kind: BhaOutlineSymbolKind,
    pub detail: Option<String>,
    pub line: usize,
    pub end_line: usize,
    pub children: Vec<BhaOutlineNode>,
    pub is_expanded: bool,
}

/// Outline view model.
#[derive(Debug, Clone)]
pub struct BhaOutlineModel {
    pub root_nodes: Vec<BhaOutlineNode>,
    pub is_visible: bool,
    pub sort_by_position: bool,
    pub filter_text: String,
    pub selected_path: Vec<usize>,
}

impl BhaOutlineModel {
    pub fn new() -> Self {
        Self { root_nodes: Vec::new(), is_visible: true, sort_by_position: true, filter_text: String::new(), selected_path: Vec::new() }
    }

    pub fn set_symbols(&mut self, nodes: Vec<BhaOutlineNode>) { self.root_nodes = nodes; }

    pub fn toggle_sort(&mut self) { self.sort_by_position = !self.sort_by_position; }

    pub fn set_filter(&mut self, text: &str) { self.filter_text = text.to_string(); }

    pub fn total_symbols(&self) -> usize {
        fn count(nodes: &[BhaOutlineNode]) -> usize {
            nodes.iter().map(|n| 1 + count(&n.children)).sum()
        }
        count(&self.root_nodes)
    }

    pub fn depth(&self) -> usize {
        fn measure(nodes: &[BhaOutlineNode]) -> usize {
            nodes.iter().map(|n| if n.children.is_empty() { 1 } else { 1 + measure(&n.children) }).max().unwrap_or(0)
        }
        measure(&self.root_nodes)
    }

    pub fn symbol_at_line(&self, line: usize) -> Option<&BhaOutlineNode> {
        fn find<'a>(nodes: &'a [BhaOutlineNode], line: usize) -> Option<&'a BhaOutlineNode> {
            for n in nodes {
                if line >= n.line && line <= n.end_line {
                    if let Some(child) = find(&n.children, line) { return Some(child); }
                    return Some(n);
                }
            }
            None
        }
        find(&self.root_nodes, line)
    }

    pub fn toggle_visibility(&mut self) { self.is_visible = !self.is_visible; }
}


// bhb_ Editor Notification Model

/// Notification severity level.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BhbNotificationSeverity { Info, Warning, Error }

/// Notification action button.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BhbNotificationAction { pub label: String, pub command_id: String }

/// A notification message.
#[derive(Debug, Clone)]
pub struct BhbNotification {
    pub id: u64,
    pub severity: BhbNotificationSeverity,
    pub message: String,
    pub source: Option<String>,
    pub actions: Vec<BhbNotificationAction>,
    pub is_read: bool,
    pub is_dismissed: bool,
}

/// Notification center model.
#[derive(Debug, Clone)]
pub struct BhbNotificationCenter {
    notifications: Vec<BhbNotification>,
    next_id: u64,
    do_not_disturb: bool,
}

impl BhbNotificationCenter {
    pub fn new() -> Self { Self { notifications: Vec::new(), next_id: 1, do_not_disturb: false } }

    pub fn notify(&mut self, severity: BhbNotificationSeverity, message: &str) -> u64 {
        let id = self.next_id; self.next_id += 1;
        self.notifications.push(BhbNotification { id, severity, message: message.to_string(), source: None, actions: Vec::new(), is_read: false, is_dismissed: false });
        id
    }

    pub fn dismiss(&mut self, id: u64) { if let Some(n) = self.notifications.iter_mut().find(|n| n.id == id) { n.is_dismissed = true; } }
    pub fn mark_read(&mut self, id: u64) { if let Some(n) = self.notifications.iter_mut().find(|n| n.id == id) { n.is_read = true; } }
    pub fn dismiss_all(&mut self) { for n in &mut self.notifications { n.is_dismissed = true; } }

    pub fn unread_count(&self) -> usize { self.notifications.iter().filter(|n| !n.is_read && !n.is_dismissed).count() }
    pub fn active_notifications(&self) -> Vec<&BhbNotification> { self.notifications.iter().filter(|n| !n.is_dismissed).collect() }
    pub fn total(&self) -> usize { self.notifications.len() }

    pub fn toggle_dnd(&mut self) { self.do_not_disturb = !self.do_not_disturb; }
    pub fn is_dnd(&self) -> bool { self.do_not_disturb }

    pub fn clear_all(&mut self) { self.notifications.clear(); }
}


// bhc_ Editor Status Bar Model

/// Status bar alignment.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BhcStatusBarAlignment { Left, Right }

/// A status bar item.
#[derive(Debug, Clone)]
pub struct BhcStatusBarItem {
    pub id: String,
    pub text: String,
    pub tooltip: Option<String>,
    pub command: Option<String>,
    pub alignment: BhcStatusBarAlignment,
    pub priority: i32,
    pub is_visible: bool,
    pub color: Option<String>,
    pub background_color: Option<String>,
}

/// Status bar model.
#[derive(Debug, Clone)]
pub struct BhcStatusBarModel {
    items: Vec<BhcStatusBarItem>,
    is_visible: bool,
}

impl BhcStatusBarModel {
    pub fn new() -> Self { Self { items: Vec::new(), is_visible: true } }

    pub fn add_item(&mut self, item: BhcStatusBarItem) { self.items.push(item); }

    pub fn remove_item(&mut self, id: &str) { self.items.retain(|i| i.id != id); }

    pub fn update_text(&mut self, id: &str, text: &str) {
        if let Some(i) = self.items.iter_mut().find(|i| i.id == id) { i.text = text.to_string(); }
    }

    pub fn left_items(&self) -> Vec<&BhcStatusBarItem> {
        let mut items: Vec<_> = self.items.iter().filter(|i| i.alignment == BhcStatusBarAlignment::Left && i.is_visible).collect();
        items.sort_by(|a, b| b.priority.cmp(&a.priority));
        items
    }

    pub fn right_items(&self) -> Vec<&BhcStatusBarItem> {
        let mut items: Vec<_> = self.items.iter().filter(|i| i.alignment == BhcStatusBarAlignment::Right && i.is_visible).collect();
        items.sort_by(|a, b| b.priority.cmp(&a.priority));
        items
    }

    pub fn toggle_visibility(&mut self) { self.is_visible = !self.is_visible; }
    pub fn is_visible(&self) -> bool { self.is_visible }
    pub fn total_items(&self) -> usize { self.items.len() }

    pub fn show_item(&mut self, id: &str) { if let Some(i) = self.items.iter_mut().find(|i| i.id == id) { i.is_visible = true; } }
    pub fn hide_item(&mut self, id: &str) { if let Some(i) = self.items.iter_mut().find(|i| i.id == id) { i.is_visible = false; } }
}


