// bhg_ Editor Explorer Tree Model

/// File explorer entry kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BhgExplorerEntryKind { File, Directory, SymLink }

/// A file explorer tree node.
#[derive(Debug, Clone)]
pub struct BhgExplorerNode {
    pub name: String,
    pub path: String,
    pub kind: BhgExplorerEntryKind,
    pub children: Vec<BhgExplorerNode>,
    pub is_expanded: bool,
    pub is_selected: bool,
}

/// Explorer tree model.
#[derive(Debug, Clone)]
pub struct BhgExplorerModel {
    pub root: Option<BhgExplorerNode>,
    pub show_hidden: bool,
}

impl BhgExplorerModel {
    pub fn new() -> Self { Self { root: None, show_hidden: false } }
    pub fn set_root(&mut self, node: BhgExplorerNode) { self.root = Some(node); }
    pub fn toggle_hidden(&mut self) { self.show_hidden = !self.show_hidden; }

    pub fn total_entries(&self) -> usize {
        fn count(n: &BhgExplorerNode) -> usize { 1 + n.children.iter().map(|c| count(c)).sum::<usize>() }
        self.root.as_ref().map(|r| count(r)).unwrap_or(0)
    }

    pub fn depth(&self) -> usize {
        fn measure(n: &BhgExplorerNode) -> usize {
            if n.children.is_empty() { 1 } else { 1 + n.children.iter().map(|c| measure(c)).max().unwrap_or(0) }
        }
        self.root.as_ref().map(|r| measure(r)).unwrap_or(0)
    }

    pub fn find_by_path(&self, path: &str) -> Option<&BhgExplorerNode> {
        fn find<'a>(n: &'a BhgExplorerNode, path: &str) -> Option<&'a BhgExplorerNode> {
            if n.path == path { return Some(n); }
            for c in &n.children { if let Some(found) = find(c, path) { return Some(found); } }
            None
        }
        self.root.as_ref().and_then(|r| find(r, path))
    }

    pub fn toggle_expand(&mut self, path: &str) {
        fn toggle(n: &mut BhgExplorerNode, path: &str) -> bool {
            if n.path == path { n.is_expanded = !n.is_expanded; return true; }
            for c in &mut n.children { if toggle(c, path) { return true; } }
            false
        }
        if let Some(r) = &mut self.root { toggle(r, path); }
    }
}


// bhh_ Editor Problems Panel Model

/// Problem severity.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum BhhProblemSeverity { Error, Warning, Info, Hint }

/// A diagnostic problem entry.
#[derive(Debug, Clone)]
pub struct BhhProblem {
    pub file: String,
    pub line: usize,
    pub column: usize,
    pub end_line: usize,
    pub end_column: usize,
    pub severity: BhhProblemSeverity,
    pub message: String,
    pub source: Option<String>,
    pub code: Option<String>,
}

/// Problems panel model.
#[derive(Debug, Clone)]
pub struct BhhProblemsModel {
    problems: Vec<BhhProblem>,
    filter_text: String,
    show_errors: bool,
    show_warnings: bool,
    show_infos: bool,
}

impl BhhProblemsModel {
    pub fn new() -> Self {
        Self { problems: Vec::new(), filter_text: String::new(), show_errors: true, show_warnings: true, show_infos: true }
    }
    pub fn set_problems(&mut self, problems: Vec<BhhProblem>) { self.problems = problems; }
    pub fn set_filter(&mut self, text: &str) { self.filter_text = text.to_string(); }

    pub fn error_count(&self) -> usize { self.problems.iter().filter(|p| p.severity == BhhProblemSeverity::Error).count() }
    pub fn warning_count(&self) -> usize { self.problems.iter().filter(|p| p.severity == BhhProblemSeverity::Warning).count() }
    pub fn info_count(&self) -> usize { self.problems.iter().filter(|p| p.severity == BhhProblemSeverity::Info || p.severity == BhhProblemSeverity::Hint).count() }
    pub fn total(&self) -> usize { self.problems.len() }

    pub fn problems_for_file(&self, file: &str) -> Vec<&BhhProblem> {
        self.problems.iter().filter(|p| p.file == file).collect()
    }

    pub fn filtered_problems(&self) -> Vec<&BhhProblem> {
        self.problems.iter().filter(|p| {
            match p.severity {
                BhhProblemSeverity::Error => self.show_errors,
                BhhProblemSeverity::Warning => self.show_warnings,
                BhhProblemSeverity::Info | BhhProblemSeverity::Hint => self.show_infos,
            }
        }).filter(|p| {
            self.filter_text.is_empty() || p.message.contains(&self.filter_text) || p.file.contains(&self.filter_text)
        }).collect()
    }

    pub fn toggle_errors(&mut self) { self.show_errors = !self.show_errors; }
    pub fn toggle_warnings(&mut self) { self.show_warnings = !self.show_warnings; }
    pub fn clear(&mut self) { self.problems.clear(); }

    pub fn affected_files(&self) -> Vec<&str> {
        let mut f: Vec<&str> = self.problems.iter().map(|p| p.file.as_str()).collect();
        f.sort(); f.dedup(); f
    }
}


// bhi_ Editor Output Channel Model

/// An output channel in the output panel.
#[derive(Debug, Clone)]
pub struct BhiOutputChannel {
    pub id: String,
    pub name: String,
    pub content: String,
    pub is_log: bool,
    pub max_lines: usize,
}

/// Output panel model.
#[derive(Debug, Clone)]
pub struct BhiOutputModel {
    channels: Vec<BhiOutputChannel>,
    active_channel_id: Option<String>,
}

impl BhiOutputModel {
    pub fn new() -> Self { Self { channels: Vec::new(), active_channel_id: None } }

    pub fn create_channel(&mut self, id: &str, name: &str, is_log: bool) {
        self.channels.push(BhiOutputChannel { id: id.to_string(), name: name.to_string(), content: String::new(), is_log, max_lines: 10000 });
        if self.active_channel_id.is_none() { self.active_channel_id = Some(id.to_string()); }
    }

    pub fn append(&mut self, channel_id: &str, text: &str) {
        if let Some(ch) = self.channels.iter_mut().find(|c| c.id == channel_id) {
            ch.content.push_str(text);
            let line_count = ch.content.lines().count();
            if line_count > ch.max_lines {
                let excess = line_count - ch.max_lines;
                let mut removed = 0;
                let mut pos = 0;
                for (i, c) in ch.content.char_indices() { if c == '\n' { removed += 1; if removed >= excess { pos = i + 1; break; } } }
                ch.content = ch.content[pos..].to_string();
            }
        }
    }

    pub fn clear_channel(&mut self, channel_id: &str) {
        if let Some(ch) = self.channels.iter_mut().find(|c| c.id == channel_id) { ch.content.clear(); }
    }

    pub fn set_active(&mut self, id: &str) { self.active_channel_id = Some(id.to_string()); }

    pub fn active_channel(&self) -> Option<&BhiOutputChannel> {
        self.active_channel_id.as_ref().and_then(|id| self.channels.iter().find(|c| &c.id == id))
    }

    pub fn remove_channel(&mut self, id: &str) { self.channels.retain(|c| c.id != id); }
    pub fn channel_count(&self) -> usize { self.channels.len() }
    pub fn channel_names(&self) -> Vec<&str> { self.channels.iter().map(|c| c.name.as_str()).collect() }
}


// bhj_ Editor Debug Console Model

/// Debug console entry kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BhjConsoleEntryKind { Input, Output, Error, Warning, Info }

/// A debug console entry.
#[derive(Debug, Clone)]
pub struct BhjConsoleEntry {
    pub kind: BhjConsoleEntryKind,
    pub text: String,
    pub source: Option<String>,
    pub line: Option<usize>,
}

/// Debug console model.
#[derive(Debug, Clone)]
pub struct BhjDebugConsole {
    entries: Vec<BhjConsoleEntry>,
    input_history: Vec<String>,
    history_index: Option<usize>,
    current_input: String,
}

impl BhjDebugConsole {
    pub fn new() -> Self { Self { entries: Vec::new(), input_history: Vec::new(), history_index: None, current_input: String::new() } }

    pub fn add_output(&mut self, text: &str) { self.entries.push(BhjConsoleEntry { kind: BhjConsoleEntryKind::Output, text: text.to_string(), source: None, line: None }); }
    pub fn add_error(&mut self, text: &str) { self.entries.push(BhjConsoleEntry { kind: BhjConsoleEntryKind::Error, text: text.to_string(), source: None, line: None }); }

    pub fn execute_input(&mut self, input: &str) {
        self.entries.push(BhjConsoleEntry { kind: BhjConsoleEntryKind::Input, text: input.to_string(), source: None, line: None });
        self.input_history.push(input.to_string());
        self.history_index = None;
        self.current_input.clear();
    }

    pub fn history_prev(&mut self) -> Option<&str> {
        if self.input_history.is_empty() { return None; }
        let idx = match self.history_index {
            Some(i) if i > 0 => i - 1,
            None => self.input_history.len() - 1,
            _ => return self.input_history.first().map(|s| s.as_str()),
        };
        self.history_index = Some(idx);
        self.input_history.get(idx).map(|s| s.as_str())
    }

    pub fn history_next(&mut self) -> Option<&str> {
        if let Some(i) = self.history_index {
            if i + 1 < self.input_history.len() {
                self.history_index = Some(i + 1);
                return self.input_history.get(i + 1).map(|s| s.as_str());
            }
            self.history_index = None;
        }
        None
    }

    pub fn set_input(&mut self, text: &str) { self.current_input = text.to_string(); }
    pub fn current_input(&self) -> &str { &self.current_input }
    pub fn entry_count(&self) -> usize { self.entries.len() }
    pub fn clear(&mut self) { self.entries.clear(); }
    pub fn entries(&self) -> &[BhjConsoleEntry] { &self.entries }
}



/// Search match within a file (bhk_)
#[derive(Debug, Clone, PartialEq)]
pub struct BhkSearchMatch {
    pub line: usize,
    pub col_start: usize,
    pub col_end: usize,
    pub preview: String,
}

/// File with search matches (bhk_)
#[derive(Debug, Clone, PartialEq)]
pub struct BhkFileMatches {
    pub path: String,
    pub matches: Vec<BhkSearchMatch>,
}

/// Search query configuration (bhk_)
#[derive(Debug, Clone, PartialEq)]
pub struct BhkSearchQuery {
    pub pattern: String,
    pub is_regex: bool,
    pub case_sensitive: bool,
    pub whole_word: bool,
    pub include_glob: Option<String>,
    pub exclude_glob: Option<String>,
}

/// Search view model (bhk_)
#[derive(Debug, Clone)]
pub struct BhkSearchView {
    pub query: Option<BhkSearchQuery>,
    pub results: Vec<BhkFileMatches>,
    pub replace_pattern: Option<String>,
    pub is_searching: bool,
    pub total_matches: usize,
}

impl BhkSearchView {
    pub fn new() -> Self {
        Self { query: None, results: Vec::new(), replace_pattern: None, is_searching: false, total_matches: 0 }
    }
    pub fn start_search(&mut self, query: BhkSearchQuery) {
        self.query = Some(query);
        self.results.clear();
        self.total_matches = 0;
        self.is_searching = true;
    }
    pub fn add_file_matches(&mut self, fm: BhkFileMatches) {
        self.total_matches += fm.matches.len();
        self.results.push(fm);
    }
    pub fn finish_search(&mut self) { self.is_searching = false; }
    pub fn file_count(&self) -> usize { self.results.len() }
    pub fn set_replace(&mut self, pat: String) { self.replace_pattern = Some(pat); }
    pub fn clear(&mut self) {
        self.query = None;
        self.results.clear();
        self.replace_pattern = None;
        self.total_matches = 0;
        self.is_searching = false;
    }
}


/// Timeline entry source (bhl_)
#[derive(Debug, Clone, PartialEq)]
pub enum BhlTimelineSource {
    Git,
    LocalHistory,
    Extension(String),
}

/// Timeline entry (bhl_)
#[derive(Debug, Clone, PartialEq)]
pub struct BhlTimelineEntry {
    pub id: String,
    pub label: String,
    pub description: Option<String>,
    pub timestamp: u64,
    pub source: BhlTimelineSource,
}

/// Timeline view model (bhl_)
#[derive(Debug, Clone)]
pub struct BhlTimelineView {
    pub file_path: Option<String>,
    pub entries: Vec<BhlTimelineEntry>,
    pub sources_enabled: Vec<BhlTimelineSource>,
}

impl BhlTimelineView {
    pub fn new() -> Self {
        Self { file_path: None, entries: Vec::new(), sources_enabled: vec![BhlTimelineSource::Git, BhlTimelineSource::LocalHistory] }
    }
    pub fn set_file(&mut self, path: String) {
        self.file_path = Some(path);
        self.entries.clear();
    }
    pub fn add_entry(&mut self, entry: BhlTimelineEntry) {
        let pos = self.entries.partition_point(|e| e.timestamp >= entry.timestamp);
        self.entries.insert(pos, entry);
    }
    pub fn entries_by_source(&self, src: &BhlTimelineSource) -> Vec<&BhlTimelineEntry> {
        self.entries.iter().filter(|e| &e.source == src).collect()
    }
    pub fn toggle_source(&mut self, src: BhlTimelineSource) {
        if let Some(idx) = self.sources_enabled.iter().position(|s| s == &src) {
            self.sources_enabled.remove(idx);
        } else {
            self.sources_enabled.push(src);
        }
    }
    pub fn is_source_enabled(&self, src: &BhlTimelineSource) -> bool {
        self.sources_enabled.contains(src)
    }
    pub fn latest_entry(&self) -> Option<&BhlTimelineEntry> {
        self.entries.first()
    }
    pub fn entry_count(&self) -> usize { self.entries.len() }
}


/// Extension state (bhm_)
#[derive(Debug, Clone, PartialEq)]
pub enum BhmExtensionState {
    Installed,
    Disabled,
    Uninstalled,
}

/// Extension info (bhm_)
#[derive(Debug, Clone, PartialEq)]
pub struct BhmExtensionInfo {
    pub id: String,
    pub name: String,
    pub publisher: String,
    pub version: String,
    pub description: String,
    pub state: BhmExtensionState,
    pub rating: Option<f64>,
    pub install_count: u64,
}

/// Extensions view model (bhm_)
#[derive(Debug, Clone)]
pub struct BhmExtensionsView {
    pub extensions: Vec<BhmExtensionInfo>,
    pub search_query: Option<String>,
    pub filter: Option<BhmExtensionState>,
}

impl BhmExtensionsView {
    pub fn new() -> Self {
        Self { extensions: Vec::new(), search_query: None, filter: None }
    }
    pub fn add_extension(&mut self, ext: BhmExtensionInfo) {
        self.extensions.push(ext);
    }
    pub fn install(&mut self, id: &str) {
        if let Some(ext) = self.extensions.iter_mut().find(|e| e.id == id) {
            ext.state = BhmExtensionState::Installed;
        }
    }
    pub fn disable(&mut self, id: &str) {
        if let Some(ext) = self.extensions.iter_mut().find(|e| e.id == id) {
            ext.state = BhmExtensionState::Disabled;
        }
    }
    pub fn uninstall(&mut self, id: &str) {
        if let Some(ext) = self.extensions.iter_mut().find(|e| e.id == id) {
            ext.state = BhmExtensionState::Uninstalled;
        }
    }
    pub fn set_search(&mut self, q: String) { self.search_query = Some(q); }
    pub fn set_filter(&mut self, f: BhmExtensionState) { self.filter = Some(f); }
    pub fn clear_filter(&mut self) { self.filter = None; }
    pub fn filtered(&self) -> Vec<&BhmExtensionInfo> {
        self.extensions.iter().filter(|e| {
            if let Some(ref f) = self.filter { &e.state == f } else { true }
        }).filter(|e| {
            if let Some(ref q) = self.search_query { e.name.contains(q) || e.description.contains(q) } else { true }
        }).collect()
    }
    pub fn installed_count(&self) -> usize {
        self.extensions.iter().filter(|e| e.state == BhmExtensionState::Installed).count()
    }
    pub fn by_rating(&self) -> Vec<&BhmExtensionInfo> {
        let mut v: Vec<_> = self.extensions.iter().filter(|e| e.rating.is_some()).collect();
        v.sort_by(|a, b| b.rating.unwrap().partial_cmp(&a.rating.unwrap()).unwrap_or(std::cmp::Ordering::Equal));
        v
    }
}


/// Setting value type (bhn_)
#[derive(Debug, Clone, PartialEq)]
pub enum BhnSettingValue {
    Bool(bool),
    String(String),
    Number(f64),
    Enum { value: String, options: Vec<String> },
    Array(Vec<String>),
}

/// A single setting entry (bhn_)
#[derive(Debug, Clone, PartialEq)]
pub struct BhnSettingEntry {
    pub key: String,
    pub label: String,
    pub description: String,
    pub category: String,
    pub value: BhnSettingValue,
    pub default_value: BhnSettingValue,
    pub is_modified: bool,
}

/// Settings editor model (bhn_)
#[derive(Debug, Clone)]
pub struct BhnSettingsEditor {
    pub settings: Vec<BhnSettingEntry>,
    pub search_query: Option<String>,
    pub active_category: Option<String>,
}

impl BhnSettingsEditor {
    pub fn new() -> Self {
        Self { settings: Vec::new(), search_query: None, active_category: None }
    }
    pub fn add_setting(&mut self, s: BhnSettingEntry) { self.settings.push(s); }
    pub fn update_setting(&mut self, key: &str, value: BhnSettingValue) {
        if let Some(s) = self.settings.iter_mut().find(|s| s.key == key) {
            s.is_modified = value != s.default_value;
            s.value = value;
        }
    }
    pub fn reset_setting(&mut self, key: &str) {
        if let Some(s) = self.settings.iter_mut().find(|s| s.key == key) {
            s.value = s.default_value.clone();
            s.is_modified = false;
        }
    }
    pub fn set_search(&mut self, q: String) { self.search_query = Some(q); }
    pub fn set_category(&mut self, c: String) { self.active_category = Some(c); }
    pub fn categories(&self) -> Vec<String> {
        let mut cats: Vec<String> = self.settings.iter().map(|s| s.category.clone()).collect();
        cats.sort();
        cats.dedup();
        cats
    }
    pub fn filtered(&self) -> Vec<&BhnSettingEntry> {
        self.settings.iter().filter(|s| {
            if let Some(ref c) = self.active_category { &s.category == c } else { true }
        }).filter(|s| {
            if let Some(ref q) = self.search_query { s.key.contains(q) || s.label.contains(q) || s.description.contains(q) } else { true }
        }).collect()
    }
    pub fn modified_count(&self) -> usize {
        self.settings.iter().filter(|s| s.is_modified).count()
    }
}


/// Keybinding source (bho_)
#[derive(Debug, Clone, PartialEq)]
pub enum BhoKeybindingSource {
    Default,
    User,
    Extension(String),
}

/// Keybinding entry (bho_)
#[derive(Debug, Clone, PartialEq)]
pub struct BhoKeybindingEntry {
    pub key: String,
    pub command: String,
    pub when: Option<String>,
    pub source: BhoKeybindingSource,
}

/// Keyboard shortcuts editor model (bho_)
#[derive(Debug, Clone)]
pub struct BhoKeybindingsEditor {
    pub bindings: Vec<BhoKeybindingEntry>,
    pub search_query: Option<String>,
}

impl BhoKeybindingsEditor {
    pub fn new() -> Self {
        Self { bindings: Vec::new(), search_query: None }
    }
    pub fn add_binding(&mut self, b: BhoKeybindingEntry) { self.bindings.push(b); }
    pub fn remove_binding(&mut self, key: &str, command: &str) {
        self.bindings.retain(|b| !(b.key == key && b.command == command));
    }
    pub fn set_search(&mut self, q: String) { self.search_query = Some(q); }
    pub fn filtered(&self) -> Vec<&BhoKeybindingEntry> {
        self.bindings.iter().filter(|b| {
            if let Some(ref q) = self.search_query {
                b.key.contains(q) || b.command.contains(q) || b.when.as_deref().unwrap_or("").contains(q)
            } else { true }
        }).collect()
    }
    pub fn conflicts(&self) -> Vec<Vec<&BhoKeybindingEntry>> {
        let mut groups: std::collections::HashMap<&str, Vec<&BhoKeybindingEntry>> = std::collections::HashMap::new();
        for b in &self.bindings {
            groups.entry(&b.key).or_default().push(b);
        }
        groups.into_values().filter(|v| v.len() > 1).collect()
    }
    pub fn by_source(&self, src: &BhoKeybindingSource) -> Vec<&BhoKeybindingEntry> {
        self.bindings.iter().filter(|b| &b.source == src).collect()
    }
    pub fn reset_key(&mut self, key: &str) {
        self.bindings.retain(|b| !(b.key == key && b.source == BhoKeybindingSource::User));
    }
    pub fn binding_count(&self) -> usize { self.bindings.len() }
}


/// Walkthrough step state (bhp_)
#[derive(Debug, Clone, PartialEq)]
pub enum BhpStepState {
    NotStarted,
    InProgress,
    Complete,
}

/// Walkthrough step (bhp_)
#[derive(Debug, Clone, PartialEq)]
pub struct BhpWalkthroughStep {
    pub id: String,
    pub title: String,
    pub description: String,
    pub state: BhpStepState,
    pub command: Option<String>,
}

/// Walkthrough category (bhp_)
#[derive(Debug, Clone)]
pub struct BhpWalkthroughCategory {
    pub id: String,
    pub title: String,
    pub steps: Vec<BhpWalkthroughStep>,
}

impl BhpWalkthroughCategory {
    pub fn new(id: String, title: String) -> Self {
        Self { id, title, steps: Vec::new() }
    }
    pub fn add_step(&mut self, step: BhpWalkthroughStep) { self.steps.push(step); }
    pub fn complete_step(&mut self, step_id: &str) {
        if let Some(s) = self.steps.iter_mut().find(|s| s.id == step_id) {
            s.state = BhpStepState::Complete;
        }
    }
    pub fn progress(&self) -> (usize, usize) {
        let done = self.steps.iter().filter(|s| s.state == BhpStepState::Complete).count();
        (done, self.steps.len())
    }
    pub fn is_complete(&self) -> bool {
        let (done, total) = self.progress();
        total > 0 && done == total
    }
}

/// Welcome view model (bhp_)
#[derive(Debug, Clone)]
pub struct BhpWelcomeView {
    pub categories: Vec<BhpWalkthroughCategory>,
    pub show_on_startup: bool,
}

impl BhpWelcomeView {
    pub fn new() -> Self { Self { categories: Vec::new(), show_on_startup: true } }
    pub fn add_category(&mut self, cat: BhpWalkthroughCategory) { self.categories.push(cat); }
    pub fn toggle_startup(&mut self) { self.show_on_startup = !self.show_on_startup; }
    pub fn all_complete(&self) -> bool { self.categories.iter().all(|c| c.is_complete()) }
    pub fn category_count(&self) -> usize { self.categories.len() }
}


/// Diff hunk (bhq_)
#[derive(Debug, Clone, PartialEq)]
pub struct BhqDiffHunk {
    pub original_start: usize,
    pub original_count: usize,
    pub modified_start: usize,
    pub modified_count: usize,
}

/// Diff view mode (bhq_)
#[derive(Debug, Clone, PartialEq)]
pub enum BhqDiffViewMode {
    SideBySide,
    Inline,
}

/// Diff editor model (bhq_)
#[derive(Debug, Clone)]
pub struct BhqDiffEditor {
    pub original_path: String,
    pub modified_path: String,
    pub hunks: Vec<BhqDiffHunk>,
    pub view_mode: BhqDiffViewMode,
    pub ignore_whitespace: bool,
    pub current_hunk: usize,
}

impl BhqDiffEditor {
    pub fn new(orig: String, modified: String) -> Self {
        Self { original_path: orig, modified_path: modified, hunks: Vec::new(), view_mode: BhqDiffViewMode::SideBySide, ignore_whitespace: false, current_hunk: 0 }
    }
    pub fn add_hunk(&mut self, h: BhqDiffHunk) { self.hunks.push(h); }
    pub fn next_hunk(&mut self) {
        if !self.hunks.is_empty() { self.current_hunk = (self.current_hunk + 1) % self.hunks.len(); }
    }
    pub fn prev_hunk(&mut self) {
        if !self.hunks.is_empty() { self.current_hunk = if self.current_hunk == 0 { self.hunks.len() - 1 } else { self.current_hunk - 1 }; }
    }
    pub fn toggle_view_mode(&mut self) {
        self.view_mode = match self.view_mode { BhqDiffViewMode::SideBySide => BhqDiffViewMode::Inline, BhqDiffViewMode::Inline => BhqDiffViewMode::SideBySide };
    }
    pub fn toggle_whitespace(&mut self) { self.ignore_whitespace = !self.ignore_whitespace; }
    pub fn hunk_count(&self) -> usize { self.hunks.len() }
    pub fn current(&self) -> Option<&BhqDiffHunk> { self.hunks.get(self.current_hunk) }
    pub fn total_added(&self) -> usize { self.hunks.iter().map(|h| h.modified_count).sum() }
    pub fn total_removed(&self) -> usize { self.hunks.iter().map(|h| h.original_count).sum() }
}


/// Merge conflict resolution (bhr_)
#[derive(Debug, Clone, PartialEq)]
pub enum BhrMergeResolution {
    Unresolved,
    AcceptCurrent,
    AcceptIncoming,
    AcceptBoth,
    Custom(String),
}

/// Merge conflict region (bhr_)
#[derive(Debug, Clone, PartialEq)]
pub struct BhrConflictRegion {
    pub id: usize,
    pub base_start: usize,
    pub base_end: usize,
    pub current_text: String,
    pub incoming_text: String,
    pub resolution: BhrMergeResolution,
}

/// Merge editor model (bhr_)
#[derive(Debug, Clone)]
pub struct BhrMergeEditor {
    pub file_path: String,
    pub conflicts: Vec<BhrConflictRegion>,
    pub result_text: Option<String>,
}

impl BhrMergeEditor {
    pub fn new(path: String) -> Self {
        Self { file_path: path, conflicts: Vec::new(), result_text: None }
    }
    pub fn add_conflict(&mut self, c: BhrConflictRegion) { self.conflicts.push(c); }
    pub fn resolve(&mut self, id: usize, res: BhrMergeResolution) {
        if let Some(c) = self.conflicts.iter_mut().find(|c| c.id == id) {
            c.resolution = res;
        }
    }
    pub fn is_fully_resolved(&self) -> bool {
        !self.conflicts.is_empty() && self.conflicts.iter().all(|c| c.resolution != BhrMergeResolution::Unresolved)
    }
    pub fn unresolved_count(&self) -> usize {
        self.conflicts.iter().filter(|c| c.resolution == BhrMergeResolution::Unresolved).count()
    }
    pub fn conflict_count(&self) -> usize { self.conflicts.len() }
    pub fn set_result(&mut self, text: String) { self.result_text = Some(text); }
    pub fn resolved_text(&self, id: usize) -> Option<String> {
        self.conflicts.iter().find(|c| c.id == id).map(|c| match &c.resolution {
            BhrMergeResolution::AcceptCurrent => c.current_text.clone(),
            BhrMergeResolution::AcceptIncoming => c.incoming_text.clone(),
            BhrMergeResolution::AcceptBoth => format!("{}\n{}", c.current_text, c.incoming_text),
            BhrMergeResolution::Custom(t) => t.clone(),
            BhrMergeResolution::Unresolved => String::new(),
        })
    }
}


/// Playground language (bhs_)
