    #[test]
    fn test_bfx_select() {
        let mut p = BfxRefactoringPreview::new("test");
        p.set_changes(vec![
            BfxPreviewChange { file: "a.rs".into(), original_text: "".into(), new_text: "".into(), line: 1, is_checked: true },
        ]);
        p.select(0);
        assert_eq!(p.selected_index, Some(0));
    }

