        let mut s = BiqLogService::new(BiqLogLevel::Trace, 3);
        for i in 0..5 {
            s.log(BiqLogEntry { level: BiqLogLevel::Info, message: format!("m{i}"), source: "s".into(), timestamp: i });
        }
        assert_eq!(s.entry_count(), 3);
