    fn test_biq_clear() {
        let mut s = BiqLogService::new(BiqLogLevel::Trace, 100);
        s.log(BiqLogEntry { level: BiqLogLevel::Info, message: "x".into(), source: "s".into(), timestamp: 1 });
        s.clear();
        assert_eq!(s.entry_count(), 0);
    }
