    #[test]
    fn test_biq_trace_level() {
        let mut s = BiqLogService::new(BiqLogLevel::Trace, 100);
        s.log(BiqLogEntry { level: BiqLogLevel::Trace, message: "t".into(), source: "s".into(), timestamp: 1 });
        assert_eq!(s.entry_count(), 1);
    }
